//! Core enumerable trait.
//! `std.collections.Enumerable` is the portable contract for user-facing
//! collection consumption operations.

module std.collections.Enumerable.

/// Enumerable connects a unary collection constructor `C[_]` to the item type
/// it contains.
/// Input: collection constructor `C[_]`.
/// Output: a trait requiring effectful consumption and value transformation
/// methods.
/// Transformation: exposes collection behavior through callbacks while leaving
/// traversal-state creation to `std.collections.Iterable`.

pub trait Enumerable[C[_]] {
    each[T](collection: C[T], cb: (T) -> Unit): Unit.
    filter[T](collection: C[T], predicate: (T) -> Bool): C[T].
    fold[T, U](collection: C[T], initial: U, reducer: (U, T) -> U): U.
    map[T, U](collection: C[T], cb: (T) -> U): C[U].
}.

pub impl Enumerable[std.collections.List] for std.collections.List {
}.

pub impl Enumerable[std.collections.Set] for std.collections.Set {
}.

//! Core index access traits.
//! `std.collections.Index` defines the portable contracts that bracket syntax
//! resolves through when a collection-like type supports indexed access.

module std.collections.Index.

/// Describes read access through `collection[index]`.
/// Input: collection type `C`, index type `I`, and yielded value type `T`.
/// Output: a trait requiring `get_at(collection, index)`.
/// Transformation: lets the compiler typecheck bracket-read syntax without
/// hardcoding every indexable collection into the parser or typechecker.

pub trait IndexGet[C, I, T] {
    get_at(collection: C, index: I): T.
}.

/// Describes write access through `collection[index] = value`.
/// Input: collection type `C`, index type `I`, and assigned value type `T`.
/// Output: `Unit` after the indexed update is accepted.
/// Transformation: gives bracket-assignment syntax a trait contract while the
/// lowering phase decides whether a target uses in-place mutation, rebinding, or
/// another backend-specific update strategy.

pub trait IndexSet[C, I, T] {
    set_at(mut collection: C, index: I, value: T): Unit.
}.

//! Core iterable trait.
//! `std.collections.Iterable` is the portable contract used by collection traversal.

module std.collections.Iterable.

/// Iterable connects a collection type `C` to the item type `T` it yields.
/// Input: collection type `C` and yielded item type `T`.
/// Output: a trait requiring an `iterator(collection)` method.
/// Transformation: exposes traversal as explicit state creation instead of
/// depending on a platform-native iterator protocol.

pub trait Iterable[C, T] {
    iterator(collection: C): std.collections.Iterator[T].
}.

pub impl Iterable[std.collections.List[T], T] for std.collections.List[T] {
}.

pub impl Iterable[std.collections.Map[K, V], {K, V}] for std.collections.Map[K, V] {
}.

pub impl Iterable[std.collections.Set[T], T] for std.collections.Set[T] {
}.

//! Core iterator contract.
//! `std.collections.Iterator` defines the portable state-passing shape used by
//! collection traversal.

module std.collections.Iterator.

/// Iterator represents a traversal state for values of type `T`.
/// Input: type parameter `T`.
/// Output: an opaque traversal-state type.
/// Transformation: hides the selected backend representation behind the
/// portable `std.collections.Iterator` API.

pub opaque type Iterator[T].

/// Step represents one yielded value and the next iterator state.
/// Input: type parameter `T`.
/// Output: a structural pair of the yielded value and next iterator state.
/// Transformation: makes traversal state explicit and immutable at the source
/// level.

pub type Step[T] =
    {value: T, next: Iterator[T]}.

/// Applies a callback to each value yielded by an iterator.
/// Input: one iterator state and one callback from `T` to `Unit`.
/// Output: `Unit`.
/// Transformation: repeatedly calls `next(iterator)`. When traversal is
/// exhausted, returns `Unit`. When a value is yielded, calls `cb(value)` for
/// its effect and continues with the returned next iterator state.
/// ```terlan
/// module iterator_each_example.
/// import std.collections.Iterator.{Iterator, Step}.
/// import std.core.Option.{None, Option, Some}.
/// import std.core.Unit.{Unit}.
/// pub each(iterator: Iterator[T], cb: (T) -> Unit): Unit ->
///    case next(iterator) {
///        None ->
///            Unit;
///        Some({value: value, next: rest}) ->
///            let _done = cb(value);
///            each(rest, cb)
///    }.
/// ```

pub each(iterator: Iterator[T], cb: (T) -> Unit): Unit.

/// Returns the next value and iterator state, or `None` when exhausted.
/// Input: one iterator state.
/// Output: `Some({value: value, next: next})` for the next item, or `None` when traversal
/// is complete.
/// Transformation: lowers through the compiler-owned `core.iterator.next`
/// intrinsic and advances traversal by returning a new iterator state rather
/// than mutating the current value.

@pure
pub next(iterator: Iterator[T]): std.core.Option[Step[T]].

//! Core keyed enumerable trait.
//! `std.collections.KeyedEnumerable` is the portable contract for key-value
//! collection transformations that preserve the key channel.

module std.collections.KeyedEnumerable.

/// KeyedEnumerable connects a binary key-value collection constructor `C[_, _]`
/// to collection-preserving transformations.
/// Input: key-value collection constructor `C[_, _]`.
/// Output: a trait requiring effectful consumption and value transformation
/// methods that preserve the key channel.
/// Transformation: maps `C[K, V]` to `C[K, U]` and filters back to `C[K, V]`,
/// avoiding lossy `List` fallback behavior for keyed collections.

pub trait KeyedEnumerable[C[_, _]] {
    each[K, V](collection: C[K, V], cb: ({K, V}) -> Unit): Unit.
    filter[K, V](collection: C[K, V], predicate: ({K, V}) -> Bool): C[K, V].
    fold[K, V, U](collection: C[K, V], initial: U, reducer: (U, {K, V}) -> U): U.
    map[K, V, U](collection: C[K, V], cb: (V) -> U): C[K, U].
}.

pub impl KeyedEnumerable[std.collections.Map] for std.collections.Map {
}.

