//! Core non-loggable secret value.
//! `std.core.Secret` is the portable source-level wrapper for values that must
//! not appear in logs, diagnostics, generated docs, support bundles, traces, or
//! panic/error rendering. Code that needs to cross a native boundary should pass
//! the typed `Secret` value instead of converting it to `String`.

module std.core.Secret.

/// Secret carries sensitive text while making the default display path redacted.
/// Input: no runtime input; fields are supplied by constructors.
/// Output: a typed secret wrapper.
/// Transformation: stores sensitive text under an explicit core type so generic
/// display and reporting code can reject or redact the value by type instead of
/// accidentally rendering a plain `String`.

pub struct Secret {
    value: String
}.

/// Renders a secret for diagnostics without exposing its sensitive contents.
/// Input: one `Secret` value.
/// Output: the stable redaction marker.
/// Transformation: ignores the wrapped sensitive value and returns the same
/// marker used by generic display so diagnostics cannot drift into a different
/// accidental rendering path.

@pure
pub diagnostic(secret: Secret): String.

/// Renders a secret for editor hover without exposing its sensitive contents.
/// Input: one `Secret` value.
/// Output: the stable redaction marker.
/// Transformation: ignores the wrapped sensitive value so editor integrations can
/// show the value shape without placing secret material in hover text.

@pure
pub editor_hover(secret: Secret): String.

/// Renders a secret for generated documentation without exposing its contents.
/// Input: one `Secret` value.
/// Output: the stable redaction marker.
/// Transformation: ignores the wrapped sensitive value so generated
/// documentation can show that a secret exists without serializing the secret
/// itself into docs artifacts.

@pure
pub generated_doc(secret: Secret): String.

/// Constructs a secret value.
/// Input: one sensitive string.
/// Output: a `Secret` wrapper.
/// Transformation: moves the input under the non-loggable secret type.

pub new(value: String): Secret.

/// Renders a secret for panic and error reporting without exposing its contents.
/// Input: one `Secret` value.
/// Output: the stable redaction marker.
/// Transformation: ignores the wrapped sensitive value so exceptional paths do
/// not become a fallback leak channel.

@pure
pub panic_error(secret: Secret): String.

/// Returns the stable redaction marker used for secret display.
/// Input: no value input.
/// Output: the string `"[secret]"`.
/// Transformation: centralizes the default marker so tests, diagnostics, and
/// support-bundle code use the same spelling.

@pure
pub redacted(): String.

/// Renders a secret for support bundles without exposing its sensitive contents.
/// Input: one `Secret` value.
/// Output: the stable redaction marker.
/// Transformation: ignores the wrapped sensitive value so support-bundle capture
/// can preserve the existence of a secret without storing the secret itself.

@pure
pub support_bundle(secret: Secret): String.

/// Renders a secret without exposing its sensitive contents.
/// Input: one `Secret` value.
/// Output: the stable redaction marker.
/// Transformation: ignores the wrapped sensitive value and returns
/// `redacted()`.

@pure
pub to_string(secret: Secret): String.

/// Renders a secret for VM traces without exposing its sensitive contents.
/// Input: one `Secret` value.
/// Output: the stable redaction marker.
/// Transformation: ignores the wrapped sensitive value so trace capture can
/// preserve value shape without recording secret material.

@pure
pub trace(secret: Secret): String.

pub impl not std.core.Equal[Secret].

pub impl not std.core.Ordering[Secret].

pub impl not std.core.String.Show[Secret].

//! Core UTF-8 string contract.
//! `std.core.String` defines Terlan's target-neutral text surface. `String` is
//! a primitive source-level UTF-8 value type; each backend owns the runtime
//! representation, but every backend must preserve this module's public
//! behavior.
//! This module exposes conversion traits, receiver methods on the intrinsic
//! `String` type, and module functions for operations that naturally consume
//! collections. Public operations lower through compiler-owned intrinsics so
//! portable Terlan source never depends on runtime-private modules,
//! JavaScript prototype methods, Rust crate APIs, or platform-specific
//! encodings.
//! Target-specific string types, such as `std.js.String.JsString`, must not
//! extend or redefine core `String`. They should expose their own platform API
//! and use explicit conversion traits when crossing into or out of core
//! `String`.
//! Documentation contract:
//! - `//!` comments document the module and are intended to lower to generated
//!  module documentation when targeting package documentation output.
//! - `///` comments document public types, traits, functions, and receiver
//!  methods and are intended to lower to generated item documentation.
//! - Every public API documents its inputs, outputs, and transformation.
//! - Examples use canonical Terlan source syntax and should become executable
//!  std tests as the documentation pipeline hardens.

module std.core.String.

/// Appends two `String` values.
/// Input: two UTF-8 `String` values.
/// Output: one `String` containing `left` followed by `right`.
/// Transformation: uses Terlan's string concatenation operator.
/// ```terlan
/// module string_append_example.
/// pub demo(): String ->
///    "hello".append("world").
/// ```

@pure
pub (left: String) append(right: String): String.

/// Counts encoded bytes in a `String`.
/// Input: one UTF-8 `String` value.
/// Output: the number of bytes in the canonical UTF-8 representation.
/// Transformation: lowers through the compiler-owned `core.string.byte_size`
/// intrinsic for each target backend.
/// ```terlan
/// module string_byte_size_example.
/// pub demo(): Int ->
///    "hello".byte_size().
/// ```

@pure
pub (value: String) byte_size(): Int.

/// Returns the Unicode scalar values in a `String`.
/// Input: one UTF-8 `String` value.
/// Output: a `List[String]` containing one valid Unicode scalar value per
/// element, in source order.
/// Transformation: decodes the complete string using the same text-unit
/// boundary as `String.length` and `String.reverse`. This gives parsers and
/// validation tools deterministic character iteration without exposing UTF-8
/// byte offsets or backend-specific UTF-16 code units.
/// ```terlan
/// module string_characters_example.
/// pub demo(): List[String] ->
///     "aé🙂".characters().
/// ```

@pure
pub (value: String) characters(): List[String].

/// Returns the Unicode scalar numbers in a `String`.
/// Input: one UTF-8 `String` value.
/// Output: a `List[Int]` containing one Unicode scalar number per element, in
/// source order.
/// Transformation: decodes the string once in the selected backend and stores
/// scalar integers directly. Repository scanners should prefer this compact
/// representation over allocating a managed one-character `String` per scalar.

@pure
pub (value: String) codepoints(): List[Int].

/// Compares two `String` values using the selected stable source ordering.
/// Input: two UTF-8 `String` values.
/// Output: `Lt` when `left` sorts before `right`, `Eq` when both strings
/// are equal, and `Gt` when `left` sorts after `right`.
/// Transformation: maps Terlan's selected string ordering relation onto
/// `std.core.Ordering.Comparison` without changing either input.
/// This ordinary Terlan implementation supplies
/// `std.core.Ordering[String]` conformance. Rich Unicode collation is
/// not part of this operation; it uses the language's string ordering.
/// ```terlan
/// module string_compare_example.
/// pub demo(): std.core.Ordering.Comparison ->
///    "a".compare("b").
/// ```

@pure
pub (left: String) compare(right: String): std.core.Ordering.Comparison.

/// Concatenates a list of `String` values.
/// Input: a `List[String]`.
