/// Result of one streaming labeled-file content audit.
/// The digest uses the same caller-ordered label/file-digest framing as
/// `sha256_labeled_file_digests`. `portable` is false when any supplied
/// forbidden UTF-8 fragment occurs, including across internal read chunks.

pub struct LabeledFileAudit {
    file_count: Int,
    digest: String,
    portable: Bool
}.

/// One generated-artifact inventory id and its repository-relative pattern.
/// Patterns are intentionally limited to exact paths, immediate-directory
/// suffixes, and recursive-directory suffixes. The bounded grammar keeps filesystem discovery
/// deterministic and prevents validation scripts from becoming host glob
/// adapters.

pub struct LabeledFilePattern {
    id: String,
    pattern: String
}.

/// Expands bounded repository-relative patterns and streams one artifact audit.
/// Directory walks are reused within the call, every matched regular file is
/// hashed and scanned once, and no per-file record crosses the actor boundary.
/// Empty matches, duplicate paths, symbolic links, and root escapes are errors.

pub audit_labeled_file_patterns(root: String, patterns: List[LabeledFilePattern], forbidden_fragments: List[String]): Result[LabeledFileAudit, std.io.File.FileError].

/// Streams each labeled file once while computing its deterministic digest and
/// scanning for forbidden UTF-8 fragments.
/// This is the bounded validation primitive for large generated-artifact sets:
/// file contents remain outside actor heaps and are never reread by a separate
/// content-policy pass.

pub audit_labeled_files(files: List[LabeledFile], forbidden_fragments: List[String]): Result[LabeledFileAudit, std.io.File.FileError].

/// Constructs one typed labeled-file digest input.

@pure
pub labeled_file(path: String, label: String): LabeledFile.

/// Constructs one typed generated-artifact inventory pattern.

@pure
pub labeled_file_pattern(id: String, pattern: String): LabeledFilePattern.

/// Returns the lowercase SHA-256 digest of one UTF-8 string.
/// Input: `text`, encoded as UTF-8 bytes.
/// Output: exactly 64 lowercase hexadecimal characters.
/// Transformation: applies SHA-256 to the complete byte sequence and renders
/// every digest byte as two hexadecimal characters.

@pure
pub sha256(text: String): String.

/// Returns the lowercase SHA-256 digest of immutable binary data.

@pure
pub sha256_bytes(bytes: std.vm.Bytes): String.

/// Hashes an unframed UTF-8 domain, one NUL separator, and ordered
/// length-framed fields.

@pure
pub sha256_domain_framed(domain: String, fields: List[String]): String.

/// Streams one regular file through SHA-256 without materializing it in an actor heap.

pub sha256_file(path: String): Result[String, std.io.File.FileError].

/// Hashes ordered UTF-8 fields with unsigned 64-bit length framing.

@pure
pub sha256_framed(fields: List[String]): String.

/// Streams caller-ordered labeled files using the compilation-input contract.
/// Each row contributes the label byte length as an unsigned big-endian 32-bit
/// integer, the UTF-8 label, the raw file length as an unsigned big-endian
/// 64-bit integer, and the raw file contents. This preserves the established
/// Rust quality-report provenance without materializing source files in an
/// actor heap.

pub sha256_labeled_file_contents(files: List[LabeledFile]): Result[String, std.io.File.FileError].

/// Streams a deterministic digest over caller-ordered labeled files.
/// Each row contributes the normalized label, one NUL octet, the lowercase
/// SHA-256 text of the file contents, and one newline. Labels must be safe
/// relative paths. Files are streamed and never materialized in the actor heap.

pub sha256_labeled_file_digests(files: List[LabeledFile]): Result[String, std.io.File.FileError].

/// Hashes text fields joined by one NUL octet without materializing that control
/// character in Terlan source. This preserves established release-candidate
/// identities while keeping the byte framing inside the typed hash adapter.

@pure
pub sha256_nul_separated(fields: List[String]): String.

/// Streams a deterministic digest over selected files in caller order.
/// Each file contributes its normalized relative path, one NUL byte, its raw
/// contents, and one newline byte. Relative paths must remain below `root`.

pub sha256_selected_files(root: String, relative_paths: List[String]): Result[String, std.io.File.FileError].

/// Computes a deterministic digest of every regular file below one directory.
/// Files are ordered by normalized relative path; each path and streaming file
/// digest is fed into the same unsigned 64-bit framing used by `sha256_framed`.
/// Symbolic links are ignored, matching recursive directory inventory APIs.

pub sha256_tree(root: String): Result[String, std.io.File.FileError].

/// Streams and verifies a canonical SHA256SUMS manifest below one root.
/// Every non-empty row must contain a lowercase SHA-256 digest, two spaces,
/// and a relative payload path. Absolute paths, parent traversal, symlink
/// escapes, malformed rows, and digest mismatches produce `Ok(false)`; host
/// file errors retain the ordinary typed `FileError` channel.

pub verify_sha256_manifest(root: String, manifest: String): Result[Bool, std.io.File.FileError].

//! Portable JSON value contract.
//! `std.data.Json` exposes JSON parsing, rendering, and typed accessors through
//! a target-neutral Terlan API. Its first backend is Rust/NativeBoundary with
//! `serde_json`, but source code sees only `Json`, `JsonError`, and `Result`.

module std.data.Json.

/// Json represents a parsed JSON value.
/// Input: no type parameter.
/// Output: an opaque JSON handle whose runtime representation is target-owned.
/// Transformation: hides the selected target JSON representation behind a
/// stable portable API so application code does not depend on backend parser
/// internals.

pub opaque type Json.

/// JsonError is the portable error returned by JSON operations.
/// Input: includes the neutral `code` and `message` fields from
/// `std.core.Error` and adds the byte offset reported by the parser when
/// available.
/// Output: a typed error value usable anywhere `Error`-including values are
/// accepted.
/// Transformation: maps backend parser and accessor failures into a portable
/// data shape without exposing target-specific exception values.

pub struct JsonError {
    code: Atom,
    message: String,
    offset: Int
}.

/// One parent row and its nested object-array string projection.

pub struct NestedStringFieldRow {
    object: Bool,
    values: List[Option[String]],
    child_array: Bool,
    children: List[StringFieldRow]
}.

/// Strict owned projection of required scalar and array fields from one object.
/// Values preserve the caller's requested order and contain no opaque JSON
/// handles, so validation code can safely retain them across continuations.

pub struct RequiredFieldProjection {
    strings: List[String],
    ints: List[Int],
    array_lengths: List[Int]
}.

/// Strict owned scalar projection for one element of a JSON object array.
/// Input: required field names supplied to `required_field_rows`.
/// Output: string, integer, and boolean values in the caller's field order.
/// Transformation: contains no opaque JSON handles, allowing report rows to
/// cross the native boundary in bounded batches instead of once per field.

pub struct RequiredFieldRow {
    strings: List[String],
    ints: List[Int],
    bools: List[Bool]
}.

/// One row projected from a JSON array by `string_field_rows`.
/// Input: whether the source element was an object and one optional string for
/// each requested field in caller order.
/// Output: a typed, recursively owned projection with no backend JSON values.
/// Transformation: distinguishes a non-object row from an object whose fields
/// are absent or non-string, while preserving exact array and field order.

pub struct StringFieldRow {
    object: Bool,
    values: List[Option[String]]
}.

/// Creates an empty JSON array.
/// Input: no value input.
/// Output: an empty JSON array.
/// Transformation: delegates array allocation to the selected target JSON
/// capability.

pub array(): Json.

/// Reads a JSON boolean value.
/// Input: one `Json` receiver.
/// Output: `Ok(value)` when the receiver is a JSON boolean, otherwise
/// `Err(JsonError)`.
/// Transformation: validates the JSON value kind before converting it to the
/// portable `Bool` type.

@pure
pub (json: Json) as_bool(): Result[Bool, JsonError].

/// Reads a JSON floating-point value.
/// Input: one `Json` receiver.
/// Output: `Ok(value)` when the receiver is a JSON number representable as
/// `Float`, otherwise `Err(JsonError)`.
/// Transformation: validates the JSON value kind before converting it to the
/// portable `Float` type.

@pure
pub (json: Json) as_float(): Result[Float, JsonError].

/// Reads a JSON integer value.
/// Input: one `Json` receiver.
/// Output: `Ok(value)` when the receiver is a JSON integer representable as
/// `Int`, otherwise `Err(JsonError)`.
/// Transformation: validates the JSON value kind and numeric range before
/// converting it to the portable `Int` type.

@pure
pub (json: Json) as_int(): Result[Int, JsonError].

/// Reads a JSON string value.
/// Input: one `Json` receiver.
/// Output: `Ok(value)` when the receiver is a JSON string, otherwise
/// `Err(JsonError)`.
/// Transformation: validates the JSON value kind before converting it to the
/// portable `String` type.

@pure
pub (json: Json) as_string(): Result[String, JsonError].

/// Reads a JSON array element by index.
/// Input: one `Json` receiver and one zero-based index.
/// Output: `Ok(value)` when the receiver is a JSON array and the index exists,
/// otherwise `Err(JsonError)`.
/// Transformation: performs a typed JSON array lookup without exposing the
/// backend array representation.

@pure
pub (json: Json) at(index: Int): Result[Json, JsonError].

/// Creates a JSON boolean value.
/// Input: one `Bool` value.
/// Output: a `Json` value representing that boolean.
/// Transformation: maps the portable Terlan boolean into the selected target
/// JSON representation.

pub bool(value: Bool): Json.

/// Appends another array and returns the same array for fluent construction.

pub (mut json: Json) extend(values: Json): Json.

/// Creates a JSON floating-point value.
/// Input: one `Float` value.
/// Output: `Ok(json)` when the value is finite and representable as JSON,
/// otherwise `Err(JsonError)`.
/// Transformation: rejects non-finite numbers before delegating construction to
/// the selected target JSON representation.

pub float(value: Float): Result[Json, JsonError].

/// Reads an object member by key.
/// Input: one `Json` receiver and one UTF-8 object key.
/// Output: `Ok(value)` when the receiver is an object containing the key,
/// otherwise `Err(JsonError)`.
/// Transformation: performs a typed JSON object lookup without exposing the
/// backend object representation.

@pure
pub (json: Json) get(key: String): Result[Json, JsonError].

/// Creates a JSON integer value.
/// Input: one `Int` value.
/// Output: a `Json` value representing that integer.
/// Transformation: maps the portable Terlan integer into the selected target
/// JSON number representation.

pub int(value: Int): Json.

/// Returns whether a JSON value is null.
/// Input: one `Json` receiver.
/// Output: `true` when the receiver is JSON null, otherwise `false`.
/// Transformation: observes the JSON value kind without changing the receiver.

@pure
pub (json: Json) is_null(): Bool.

/// Returns the sorted member names of a JSON object.
/// Input: one `Json` receiver.
/// Output: `Ok(keys)` when the receiver is an object, otherwise
/// `Err(JsonError)`.
/// Transformation: copies object member names into a portable `List[String]`
/// in bytewise sorted order without exposing the backend map representation.

@pure
pub (json: Json) keys(): Result[List[String], JsonError].

/// Returns the length of a JSON array.
/// Input: one `Json` receiver.
/// Output: `Ok(length)` when the receiver is a JSON array, otherwise
/// `Err(JsonError)`.
/// Transformation: validates the JSON value kind and returns the array element
/// count without exposing the backend array representation.

@pure
pub (json: Json) length(): Result[Int, JsonError].

/// Projects one object array and one nested object-array member in a single
/// native traversal.
/// Missing or non-array child members set `child_array` to `false` and return
/// no child rows. Non-object parent and child elements remain represented by
/// rows whose `object` flag is `false`.

pub (json: Json) nested_string_field_rows(parent_fields: List[String], child_array_field: String, child_fields: List[String]): Result[List[NestedStringFieldRow], JsonError].

/// Projects at most 256 nested rows beginning at a zero-based array index.

pub (json: Json) nested_string_field_rows_page(start: Int, maximum: Int, parent_fields: List[String], child_array_field: String, child_fields: List[String]): Result[List[NestedStringFieldRow], JsonError].

/// Creates a JSON null value.
/// Input: no value input.
/// Output: a `Json` value representing JSON null.
/// Transformation: delegates construction to the selected target JSON
/// capability while preserving `Json` as the only source-visible value shape.

pub null(): Json.

/// Creates an empty JSON object.
/// Input: no value input.
/// Output: an empty JSON object.
/// Transformation: delegates object allocation to the selected target JSON
/// capability.

pub object(): Json.

/// Returns the number of members in a JSON object without allocating a key list.

@pure
pub (json: Json) object_length(): Result[Int, JsonError].

/// Parses text into a JSON value.
/// Input: one UTF-8 string containing JSON source text.
/// Output: `Ok(json)` when parsing succeeds, otherwise `Err(JsonError)`.
/// Transformation: delegates parsing to the selected target JSON capability and
/// maps parser failures into `JsonError`.

pub parse(text: String): Result[Json, JsonError].

/// Appends a value to a JSON array.
/// Input: one mutable JSON array receiver and one JSON value.
/// Output: the same JSON array for fluent construction.
/// Transformation: updates the mutable receiver through the native JSON
/// builder capability without exposing the backend array representation.

pub (mut json: Json) push(value: Json): Json.

/// Inserts or replaces a member on a JSON object.
/// Input: one mutable JSON object receiver, one UTF-8 key, and one JSON value.
/// Output: the same JSON object for fluent construction.
/// Transformation: updates the mutable receiver through the native JSON
/// builder capability without exposing the backend object representation.

pub (mut json: Json) put(key: String, value: Json): Json.

/// Renders one UTF-8 string as a complete canonical JSON string literal.
/// This pure helper lets deterministic report generators construct JSON text
/// without allocating one opaque native JSON handle per scalar field. Quotes,
/// reverse solidus, and ASCII control bytes are escaped; all other UTF-8 text
/// is preserved exactly.

@pure
pub quote_string(value: String): String.

/// Removes one existing member from a JSON object.
/// Input: a mutable JSON object receiver and one UTF-8 member key.
/// Output: the same JSON object for fluent mutation.
/// Transformation: removes exactly one existing member without exposing the
/// backend object representation; a non-object receiver or missing key fails
/// through the native JSON error boundary.

pub (mut json: Json) remove(key: String): Json.

/// Projects required scalar fields from every element of a JSON object array.
/// Input: a JSON array plus ordered required string, integer, and boolean field
/// names. Output: one fully owned `RequiredFieldRow` per source element.
/// Transformation: validates and projects the complete array in one native
/// traversal. A non-object row, missing field, or type mismatch returns a typed
/// `JsonError` whose offset identifies the failing row.

pub (json: Json) required_field_rows(string_fields: List[String], int_fields: List[String], bool_fields: List[String]): Result[List[RequiredFieldRow], JsonError].

/// Projects one bounded page of required scalar object-array fields.
/// At most 256 rows are returned. `start` is zero-based and `maximum` must be
/// between 1 and 256, keeping native-to-managed conversion within the VM's
/// public-value budget while preserving stable source order.

pub (json: Json) required_field_rows_page(start: Int, maximum: Int, string_fields: List[String], int_fields: List[String], bool_fields: List[String]): Result[List[RequiredFieldRow], JsonError].

/// Projects required string, integer, and array-length fields in one native
/// operation. Missing fields and type mismatches are typed `JsonError` values;
/// the returned projection is ordinary owned Terlan data.

pub (json: Json) required_fields(string_fields: List[String], int_fields: List[String], array_fields: List[String]): Result[RequiredFieldProjection, JsonError].

/// Replaces one existing JSON array element.
/// Input: a mutable JSON array receiver, a zero-based index, and a JSON value.
/// Output: the same JSON array when the index exists; invalid receivers and indices fail at
/// the native boundary with the same stable errors as `at`.
/// Transformation: replaces exactly one owned array element without exposing
/// or aliasing the backend JSON representation.

pub (mut json: Json) set(index: Int, value: Json): Json.

/// Creates a JSON string value.
/// Input: one UTF-8 `String` value.
/// Output: a `Json` value representing that string.
/// Transformation: maps the portable Terlan string into the selected target
/// JSON string representation.

pub string(value: String): Json.

/// Projects optional string fields from every element of a JSON object array.
/// Input: a JSON array and an ordered list of object field names.
/// Output: one `StringFieldRow` per array element. Object rows contain
/// `Some(text)` only for string-valued requested fields; absent and non-string
/// fields become `None`. Non-object elements set `object` to `false`.
/// Transformation: performs one typed native traversal and returns only owned
/// Terlan values, avoiding per-field opaque-handle calls for large manifests.

pub (json: Json) string_field_rows(fields: List[String]): Result[List[StringFieldRow], JsonError].

/// Projects optional string fields from one JSON object.
/// Input: a JSON object and ordered field names.
/// Output: one optional string per requested field. Missing and non-string
/// members become `None` without exposing backend JSON values.
/// Transformation: validates the receiver and composes typed accessors in
/// Terlan source, preserving requested field order and duplicate names.

pub (json: Json) string_fields(fields: List[String]): Result[List[Option[String]], JsonError].

/// Builds a JSON array of string-valued objects from exact-width typed rows.
/// Field names must be unique and every row must contain exactly one value per
/// field. Invalid shapes return a stable `JsonError` instead of silently
/// dropping or overwriting data.

pub string_object_rows(fields: List[String], rows: List[List[String]]): Result[Json, JsonError].

/// Renders a JSON value as text.
/// Input: one `Json` value.
/// Output: `Ok(text)` when rendering succeeds, otherwise `Err(JsonError)`.
/// Transformation: delegates serialization to the selected target JSON
/// capability while preserving the portable `String` output contract.

pub stringify(json: Json): Result[String, JsonError].

/// Renders a JSON value with canonical two-space indentation.
/// Input: one `Json` value.
/// Output: `Ok(text)` containing stable multiline JSON when rendering succeeds,
/// otherwise `Err(JsonError)`.
/// Transformation: delegates pretty serialization to the selected target JSON
/// capability while retaining deterministic object-key order.

pub stringify_pretty(json: Json): Result[String, JsonError].

/// Renders a validated JSON value as compact text.
/// Input: one live `Json` value.
/// Output: its compact JSON representation, preserving escaping and key order.
/// Transformation: uses the maintained value renderer; unlike parsing arbitrary
/// text, rendering a validated JSON value requires no recoverable error branch.

pub to_string(json: Json): String.

//! Portable TOML parsing contract.
//! TOML documents lower into `std.data.Json` because both formats share
//! the object, array, string, integer, float, and boolean data model required by
//! repository manifests. This keeps one typed accessor surface while the
//! selected backend owns TOML syntax and parser errors.

module std.data.Toml.

/// Stable portable TOML parser error.

pub struct TomlError {
    code: Atom,
    message: String,
    offset: Int
}.

/// Parses one TOML document into the portable structured-data representation.
/// Input: UTF-8 TOML source text.
/// Output: `Ok(Json)` for a valid document or `Err(TomlError)` for malformed or
/// unsupported TOML syntax.
/// Transformation: delegates parsing to the selected maintained TOML backend,
/// converts recursively owned values to `Json`, and exposes no host values or
/// parser handles.

pub parse(text: String): Result[std.data.Json, TomlError].

//! Portable Postgres capability contract.
//! `std.db.Postgres` defines the source-level Postgres API for Terlan
//! applications. The VM uses an external worker backed by the maintained
//! Postgres adapter. Pools, transaction connections, and rows belong to their
//! creating actor and are released when that actor exits. Database calls suspend
//! the actor while the worker performs I/O.
//! Worker loss or an expired transport deadline can leave a mutation's outcome
//! unknown. An `Err` does not authorize retrying a write automatically.

module std.db.Postgres.

/// Config represents the minimal Postgres connection configuration.
/// Input: no type parameter.
/// Output: typed configuration record.
/// Transformation: keeps the first connection surface intentionally small
/// while leaving pool tuning and TLS options for later explicit fields.

pub type Config =
    {url: String}.

/// Connection represents one transaction-scoped Postgres connection.
/// Input: no type parameter.
/// Output: an opaque transaction connection handle.
/// Transformation: keeps transaction execution scoped to the adapter while
/// allowing Terlan code to express transaction boundaries.

pub opaque type Connection.

/// Pool represents a configured Postgres connection pool.
/// Input: no type parameter.
/// Output: an opaque pool handle.
/// Transformation: hides target-owned pool, socket, TLS, and driver state from
/// Terlan source.

pub opaque type Pool.

/// Row represents one returned Postgres row.
/// Input: no type parameter.
/// Output: an opaque row handle.
/// Transformation: hides target row storage while exposing explicit typed
/// accessors.

pub opaque type Row.

/// Reads a boolean column by name.
/// Input: one row and one column name.
/// Output: `Ok(value)` when the column exists and can decode as `Bool`,
/// otherwise `Err(Error)`.
/// Transformation: delegates typed row decoding to the Postgres adapter.

pub (row: Row) bool(name: String): Result[Bool, std.core.Error].

/// Registers a Postgres pool; its first operation opens a connection.
/// Input: one `Config`.
/// Output: `Ok(pool)` when the adapter creates a pool, otherwise `Err(Error)`.
/// Transformation: delegates connection setup to the selected Postgres runtime
/// adapter without exposing driver state to source code. URL validation happens
/// immediately; network and authentication failures can occur on the first query.

pub connect(config: Config): Result[Pool, std.core.Error].

/// Runs a SQL command and returns the affected row count.
/// Input: one pool or transaction connection, SQL text, and JSON-encoded
/// parameter values.
/// Output: `Ok(count)` when the command succeeds, otherwise `Err(Error)`.
/// Transformation: delegates command execution to the adapter and exposes only
/// the portable affected-row count.

pub execute(target: Pool | Connection, sql: String, params: List[std.data.Json]): Result[Int, std.core.Error].

/// Reads an integer column by name.
/// Input: one row and one column name.
/// Output: `Ok(value)` when the column exists and can decode as `Int`,
/// otherwise `Err(Error)`.
/// Transformation: delegates typed row decoding to the Postgres adapter.

pub (row: Row) int(name: String): Result[Int, std.core.Error].

/// Reads a JSON column by name.
/// Input: one row and one column name.
/// Output: `Ok(value)` when the column exists and can decode as `Json`,
/// otherwise `Err(Error)`.
/// Transformation: delegates typed row decoding to the Postgres adapter and
/// returns the portable JSON handle.

pub (row: Row) json(name: String): Result[std.data.Json, std.core.Error].

/// Runs a SQL query and returns all rows.
/// Input: one pool or transaction connection, SQL text, and JSON-encoded
/// parameter values.
/// Output: `Ok(rows)` when the query succeeds, otherwise `Err(Error)`.
/// Transformation: delegates SQL execution and row decoding to the Postgres
/// adapter while preserving a portable row handle surface.

pub query(target: Pool | Connection, sql: String, params: List[std.data.Json]): Result[List[Row], std.core.Error].

/// Runs a SQL query and returns at most one row.
/// Input: one pool or transaction connection, SQL text, and JSON-encoded
/// parameter values.
/// Output: `Ok(Some(row))`, `Ok(None)`, or `Err(Error)`.
/// Transformation: delegates SQL execution to the adapter and normalizes the
/// single-row result shape into `Option`.

pub query_one(target: Pool | Connection, sql: String, params: List[std.data.Json]): Result[Option[Row], std.core.Error].

/// Reads a string column by name.
/// Input: one row and one column name.
/// Output: `Ok(value)` when the column exists and can decode as `String`,
/// otherwise `Err(Error)`.
/// Transformation: delegates typed row decoding to the Postgres adapter.

pub (row: Row) string(name: String): Result[String, std.core.Error].

/// Runs a transaction body.
/// Input: one pool and one function that receives a transaction connection.
/// Output: the transaction body's result when commit succeeds, otherwise
/// `Err(Error)`.
/// Transformation: lets source code own the transaction boundary while the
/// adapter owns begin, commit, rollback, and connection lifecycle details.
/// The callback executes in the calling actor. `Ok` commits and `Err` rolls back;
/// rollback failure is returned instead of the callback error. Actor failure
/// closes the worker and its database connections. The connection handle expires
/// after either terminal attempt.

pub transaction[T](pool: Pool, body: (Connection) -> Result[T, std.core.Error]): Result[T, std.core.Error].

//! Portable Base64 encoding contract.
//! `std.encoding.Base64` exposes text-oriented Base64 helpers through a
//! target-neutral Terlan API. Its first backend is Rust/NativeBoundary with the
//! `base64` crate; source code sees only `String`, `Bytes`, `Base64Error`, and
//! `Result`.

module std.encoding.Base64.

/// Base64Error is the portable error returned by Base64 decoding operations.
/// Input: includes the neutral `code` and `message` fields from
/// `std.core.Error` and adds the byte offset reported by the decoder when
/// available.
/// Output: a typed error value usable anywhere `Error`-including values are
/// accepted.
/// Transformation: maps backend decoder failures into a portable data shape
/// without exposing target-specific exception values.

pub struct Base64Error {
    code: Atom,
    message: String,
    offset: Int
}.

/// Decodes standard Base64 text into UTF-8 text.
/// Input: one Base64 `String`.
/// Output: `Ok(text)` when decoding succeeds and the result is valid UTF-8,
/// otherwise `Err(Base64Error)`.
/// Transformation: delegates decoding to the selected target Base64 capability
/// and maps invalid input into `Base64Error`.

pub decode(text: String): Result[String, Base64Error].

/// Decodes standard Base64 text into arbitrary VM-owned bytes.
/// Input: one strictly encoded standard Base64 string.
/// Output: `Ok(bytes)` for valid input or `Err(Base64Error)` for malformed text.
/// Transformation: decodes directly into VM-owned bytes without a UTF-8
/// validation step.

pub decode_bytes(text: String): Result[std.vm.Bytes, Base64Error].

/// Decodes URL-safe Base64 text into UTF-8 text.
/// Input: one URL-safe Base64 `String`.
/// Output: `Ok(text)` when decoding succeeds and the result is valid UTF-8,
/// otherwise `Err(Base64Error)`.
/// Transformation: delegates URL-safe decoding to the selected target Base64
/// capability and maps invalid input into `Base64Error`.

pub decode_url(text: String): Result[String, Base64Error].

/// Decodes URL-safe Base64 text into arbitrary VM-owned bytes.
/// Input: one strictly encoded URL-safe Base64 string.
/// Output: `Ok(bytes)` for valid input or `Err(Base64Error)` for malformed text.
/// Transformation: decodes directly into VM-owned bytes without a UTF-8
/// validation step.

pub decode_url_bytes(text: String): Result[std.vm.Bytes, Base64Error].

/// Encodes UTF-8 text with the standard Base64 alphabet.
/// Input: one UTF-8 `String`.
/// Output: Base64 text using the standard alphabet with padding.
/// Transformation: delegates encoding to the selected target Base64 capability.

pub encode(text: String): String.

/// Encodes arbitrary VM-owned bytes with the standard Base64 alphabet.
/// Input: one immutable `Bytes` payload.
/// Output: padded Base64 text using the standard alphabet.
/// Transformation: passes the exact octets through the selected native
/// capability without interpreting them as UTF-8.

pub encode_bytes(bytes: std.vm.Bytes): String.

/// Encodes UTF-8 text with the URL-safe Base64 alphabet.
/// Input: one UTF-8 `String`.
/// Output: Base64 text using the URL-safe alphabet without relying on a
/// backend-specific encoder surface.
/// Transformation: delegates URL-safe encoding to the selected target Base64
/// capability.

pub encode_url(text: String): String.

/// Encodes arbitrary VM-owned bytes with the URL-safe Base64 alphabet.
/// Input: one immutable `Bytes` payload.
/// Output: padded Base64 text using the URL-safe alphabet.
/// Transformation: passes the exact octets through the selected URL-safe
/// native capability without interpreting them as UTF-8.

pub encode_url_bytes(bytes: std.vm.Bytes): String.

/// Encodes arbitrary bytes using URL-safe Base64 without padding.
