/// and HSTS subdomain flag.
/// Output: `SecurityHeaders`.
/// Transformation: centralizes public construction so response policy values
/// remain explicit and route-manifest-friendly.

pub constructor SecurityHeaders {
    (content_type_options: Bool, frame_options: FrameOptions, referrer_policy: ReferrerPolicy, hsts_max_age: Int, hsts_include_subdomains: Bool): SecurityHeaders ->
        SecurityHeaders {content_type_options: content_type_options, frame_options: frame_options, referrer_policy: referrer_policy, hsts_max_age: hsts_max_age, hsts_include_subdomains: hsts_include_subdomains}
}.

//! Portable HTTP router contract.
//! `std.http.Router` defines the source-level route builder used by Terlan web
//! applications. Ordinary source functions build an immutable declaration
//! sequence without opening transports. Handlers accept `Request` and return
//! `Response`. Serving executes `router/0` once per admitted image generation;
//! the HTTP package validates its returned declarations and callbacks.

module std.http.Router.

/// ChannelEndpoint represents any VM-owned long-lived HTTP channel endpoint.
/// Input: a route endpoint plan from a channel module such as
/// `std.http.WebSocket` or `std.http.Sse`.
/// Output: an opaque endpoint value accepted by channel-aware router helpers.
/// Transformation: documents the shared channel category without erasing the
/// stricter `websocket` and `sse` function signatures.

pub type ChannelEndpoint =
    WebSocketEndpoint
  | SseEndpoint.

/// Continue advances HTTP dispatch to the next middleware or route handler.
/// Input: no runtime input.
/// Output: the singleton continuation result.
/// Transformation: makes middleware continuation explicit instead of inferring
/// it from an ordinary response value.

pub type Continue =
    Atom["continue"].

/// ErrorHandler represents one router-level error handler.
/// Input: one `HttpError`.
/// Output: one `Response`.
/// Transformation: gives development and production error rendering a typed
/// callback shape without exposing backend panic, bridge, or server internals.

pub type ErrorHandler =
    (std.http.Error.HttpError) -> std.http.Response.

/// GroupBuilder configures a nested router scope.
/// Input: one scoped `Router`.
/// Output: the configured scoped `Router`.
/// Transformation: represents route-group composition as an ordinary typed
/// function value instead of special route-block syntax.

pub type GroupBuilder =
    (Router) -> Router.

/// Handler represents one HTTP route handler.
/// Input: one `Request`.
/// Output: one `Response`.
/// Transformation: gives route declarations a single reusable function type so
/// the compiler can validate handler arity and return type.

pub type Handler =
    (std.http.Request) -> std.http.Response.

/// Allows one policy-sensitive lifecycle transition.
/// Input: no payload.
/// Output: the singleton `lifecycle_allow` decision.
/// Transformation: authorizes the current transition without changing it.

pub type LifecycleAllow =
    Atom["lifecycle_allow"].

/// Result returned by source lifecycle middleware.
/// Input: no direct runtime input.
/// Output: either allow or reject.
/// Transformation: closes the policy result domain to explicit decisions.

pub type LifecycleDecision =
    LifecycleAllow
  | LifecycleReject.

/// LifecycleEvent is the closed source-visible VM HTTP transition domain.
/// Input: no direct runtime input.
/// Output: one worker, request, channel, or shutdown transition.
/// Transformation: exposes capabilities-only lifecycle metadata while keeping
/// process and stream handles opaque numeric identities.

pub type LifecycleEvent =
    {Atom["worker_start"], process: Int}
  | {Atom["request_start"], process: Int, method: String, path: String}
  | {Atom["request_end"], process: Int, method: String, path: String, outcome: LifecycleRequestOutcome}
  | {Atom["channel_bind"], process: Int, stream: Int}
  | {Atom["channel_unbind"], process: Int, stream: Int, reason: LifecycleExitReason}
  | {Atom["shutdown_handoff"], mode: Atom["drain"] | Atom["immediate"], active_handlers: Int}.

/// LifecycleExitReason describes why a VM HTTP channel stopped.
/// Input: no direct runtime input.
/// Output: the closed VM process-exit reason domain.
/// Transformation: preserves cleanup diagnostics without exposing runtime
/// implementation types.

pub type LifecycleExitReason =
    Atom["normal"]
  | Atom["killed"]
  | {Atom["error"], message: String}
  | {Atom["shutdown_timeout"], timeout_ms: Int}
  | {Atom["memory_limit_exceeded"], requested_bytes: Int, previous_bytes: Int, projected_bytes: Int}.

/// Callback invoked once for every VM HTTP lifecycle transition.
/// Input: one typed lifecycle event.
/// Output: one lifecycle decision.
/// Transformation: lets source policy observe transitions without scheduler
/// access.

pub type LifecycleMiddleware =
    (LifecycleEvent) -> LifecycleDecision.

/// Rejects one policy-sensitive lifecycle transition with a stable reason.
/// Input: one source-owned diagnostic reason.
/// Output: a tagged rejection decision.
/// Transformation: stops policy-sensitive work before it owns runtime state.

pub type LifecycleReject =
    {Atom["reject"], reason: String}.

/// LifecycleRequestOutcome describes one completed VM HTTP request.
/// Input: no direct runtime input.
/// Output: a successful status or a typed handler error message.
/// Transformation: keeps request completion observable without exposing host
/// server response objects or scheduler state.

pub type LifecycleRequestOutcome =
    {Atom["response"], status: Int}
  | {Atom["error"], message: String}.

/// Middleware represents one router middleware callback.
/// Input: one `Request`.
/// Output: one explicit `MiddlewareResult`.
/// Transformation: gives middleware registration a typed callback shape with
/// deterministic continuation and short-circuit semantics.

pub type Middleware =
    (std.http.Request) -> MiddlewareResult.

/// MiddlewareResult is the complete result domain for HTTP middleware.
/// Input: no direct runtime input.
/// Output: either `Continue` or `Respond(Response)`.
/// Transformation: prevents middleware from accidentally treating an ordinary
/// response as continuation state.

pub type MiddlewareResult =
    Continue
  | Respond.

/// OverloadPolicy selects the VM action when a router's pending-work bound is
/// reached.
/// Input: no direct runtime input.
/// Output: one of `queue`, `reject`, or `spill`.
/// Transformation: keeps overload behavior explicit and closed to unsupported
/// policy atoms before the VM admission layer consumes the router descriptor.

pub type OverloadPolicy =
    Atom["queue"]
  | Atom["reject"]
  | Atom["spill"].

/// Respond terminates HTTP dispatch with one typed response.
/// Input: one `Response`.
/// Output: a tagged middleware result containing that response.
/// Transformation: gives authorization, recovery, and timeout middleware a
/// typed short-circuit path.

pub type Respond =
    {Atom["respond"], response: std.http.Response}.

/// ResponseMiddleware represents one router response callback.
/// Input: the original `Request` and the current typed `Response`.
/// Output: the response passed to the next outer response middleware.
/// Transformation: supports deterministic post-processing without exposing
/// transport buffers or weakening the typed response contract.

pub type ResponseMiddleware =
    (std.http.Request, std.http.Response) -> std.http.Response.

/// Router represents an HTTP route table.
/// Input: no type parameter.
/// Output: an immutable route builder with private declaration storage.
/// Transformation: retains callbacks and nested scopes without opening sockets
/// or depending on compiler interpretation of builder names.

pub struct Router {
    #entries: List[Entry]
}.

/// SseEndpoint represents one VM-owned server-sent event endpoint plan.
/// Input: a bounded endpoint plan from `std.http.Sse`.
/// Output: an opaque endpoint value accepted by `Router.sse`.
/// Transformation: keeps router declarations independent from concrete stream
/// state while preserving explicit channel endpoint typing.

pub type SseEndpoint =
    std.http.Sse.Endpoint.

/// WebSocketEndpoint represents one VM-owned WebSocket endpoint plan.
/// Input: a bounded endpoint plan from `std.http.WebSocket`.
/// Output: an opaque endpoint value accepted by `Router.websocket`.
/// Transformation: keeps router declarations independent from concrete socket
/// state while preserving explicit channel endpoint typing.

pub type WebSocketEndpoint =
    std.http.WebSocket.Endpoint.

/// Adds a `DELETE` route.
/// Input: one `Router`, one route pattern, and one handler.
/// Output: the updated `Router`.
/// Transformation: appends a typed route declaration without mutating the earlier
/// router value.

pub (router: Router) delete(pattern: String, handler: Handler): Router.

/// Adds a router-level error handler.
/// Input: one `Router` and one error handler.
/// Output: the updated `Router`.
/// Transformation: adapts host failure messages into the public HttpError in
/// source, then invokes the user's recovery callback.

pub (router: Router) error(handler: ErrorHandler): Router.

/// Adds a fallback route.
/// Input: one `Router` and one handler.
/// Output: the updated `Router`.
/// Transformation: records the catch-all handler used when no method-specific
/// route matches the request.

pub (router: Router) fallback(handler: Handler): Router.

/// Adds a `GET` route.
/// Input: one `Router`, one route pattern, and one handler.
/// Output: the updated `Router`.
/// Transformation: appends a typed route declaration without mutating the earlier
/// router value.

pub (router: Router) get(pattern: String, handler: Handler): Router.

/// Adds a nested route group.
/// Input: one `Router`, one path prefix, and one group builder function.
/// Output: the updated `Router`.
/// Transformation: invokes the ordinary group-builder function once on an empty
/// router and retains its declarations under the supplied path prefix.

pub (router: Router) group(prefix: String, configure: GroupBuilder): Router.

/// Adds a `HEAD` route.
/// Input: one `Router`, one route pattern, and one handler.
/// Output: the updated `Router`.
/// Transformation: appends a typed route declaration without mutating the earlier
/// router value.

pub (router: Router) head(pattern: String, handler: Handler): Router.

/// Installs source lifecycle middleware for a root router.
/// Input: one `Router` and one typed lifecycle callback.
/// Output: the updated `Router`.
/// Transformation: records a single callback that the VM invokes before
/// policy-sensitive transitions and after non-vetoable cleanup transitions.

pub (router: Router) lifecycle(middleware: LifecycleMiddleware): Router.

/// Adds response middleware to a router scope.
/// Input: one `Router` and one response middleware callback.
/// Output: the updated `Router`.
/// Transformation: records post-processing that unwinds in reverse declaration
/// order after a handler or short-circuit response is produced.

pub (router: Router) map_response(middleware: ResponseMiddleware): Router.

/// Creates an empty router.
/// Input: no value input.
/// Output: an empty `Router`.
/// Transformation: creates an ordinary source value without allocating any live
/// transport or scheduler state.

@pure
pub new(): Router.

/// Adds an `OPTIONS` route.
/// Input: one `Router`, one route pattern, and one handler.
/// Output: the updated `Router`.
/// Transformation: appends a typed route declaration without mutating the earlier
/// router value.

pub (router: Router) options(pattern: String, handler: Handler): Router.

/// Configures bounded pending HTTP work for this router.
/// Input: one `Router`, a closed overload policy, and a positive pending-work
/// limit.
/// Output: the updated `Router`.
/// Transformation: records VM-owned admission metadata without exposing
/// scheduler internals or host-server implementation details.

pub (router: Router) overload(policy: OverloadPolicy, max_pending: Int): Router.

/// Adds a `PATCH` route.
/// Input: one `Router`, one route pattern, and one handler.
/// Output: the updated `Router`.
/// Transformation: appends a typed route declaration without mutating the earlier
/// router value.

pub (router: Router) patch(pattern: String, handler: Handler): Router.

/// Adds a `POST` route.
/// Input: one `Router`, one route pattern, and one handler.
/// Output: the updated `Router`.
/// Transformation: appends a typed route declaration without mutating the earlier
/// router value.

pub (router: Router) post(pattern: String, handler: Handler): Router.

/// Adds a `PUT` route.
/// Input: one `Router`, one route pattern, and one handler.
/// Output: the updated `Router`.
/// Transformation: appends a typed route declaration without mutating the earlier
/// router value.

pub (router: Router) put(pattern: String, handler: Handler): Router.

/// Adds a server-sent event channel route.
/// Input: one `Router`, one route pattern, and one bounded SSE endpoint plan.
/// Output: the updated `Router`.
/// Transformation: appends a typed channel declaration while the serving runtime
/// owns event-stream state and scheduling.

pub (router: Router) sse(pattern: String, endpoint: SseEndpoint): Router.

/// Adds middleware to a router scope.
/// Input: one `Router` and one middleware callback.
/// Output: the updated `Router`.
/// Transformation: retains a callback in declaration order for serving-boundary
/// admission.

pub (router: Router) use(middleware: Middleware): Router.

/// Adds a WebSocket channel route.
/// Input: one `Router`, one route pattern, and one bounded channel endpoint
/// plan.
/// Output: the updated `Router`.
/// Transformation: appends a typed channel declaration while the serving runtime
/// owns upgrade, frame, and session state.

pub (router: Router) websocket(pattern: String, endpoint: WebSocketEndpoint): Router.

//! Portable HTTP session contract.
//! `std.http.Session` exposes actor-backed session helpers used by Terlan HTTP
//! handlers. The HTTP server binds request cookies to VM session actor
//! identity; source code owns the private session record and explicit response
//! threading, identity retry, and lifetime policy. Native operations supply
//! entropy and atomically reserve or replace source-selected identities.

module std.http.Session.

/// Session represents a source-owned reference to an HTTP session actor.
/// Input: no type parameter.
/// Output: a managed record with private identity, pending-cookie, and lifetime fields.
/// Transformation: hides actor ids, VM table ids, sticky routing metadata, and
/// recovery policy while preserving a stable handler-facing session value.

pub struct Session {
    #identity: String,
    #pending_identity: String,
    #ttl_seconds: Int
}.

/// Returns the current request session.
/// Input: one HTTP `Request`.
/// Output: the VM-owned session actor bound to the request cookie, creating one
/// when the request has no valid session cookie.
/// Transformation: selects a cookie identity, reuses a live lookup, and requests
/// fresh allocation only on absence. Storage errors propagate without replacement.

pub current(request: std.http.Request): Session.

/// Deletes one session value.
/// Input: one mutable `Session` receiver and one string key.
/// Output: `Unit`.
/// Transformation: removes VM table state through the session actor boundary.

pub (mut session: Session) delete(key: String): Unit.

/// Expires the session.
/// Input: one mutable `Session` receiver.
/// Output: `Unit`.
/// Transformation: requests cleanup of the VM session actor and its owned table
/// state; future use of the stale handle must fail through runtime diagnostics.

pub (mut session: Session) expire(): Unit.

/// Reads one session value.
/// Input: one `Session` receiver and one string key.
/// Output: `Some(value)` when the session contains `key`, otherwise `None`.
/// Transformation: reads VM table state owned by the session actor without
/// exposing the backing table handle.

pub (session: Session) get(key: String): Option[String].

/// Rotates the session id.
/// Input: one mutable `Session` receiver.
/// Output: the same VM session actor with a new public session id.
/// Transformation: preserves actor-owned table state while requiring the HTTP
/// runtime to thread a replacement session cookie into the response.

pub (mut session: Session) rotate(): Session.

/// Writes one session value.
/// Input: one mutable `Session` receiver, one string key, and one string value.
/// Output: `Unit`.
/// Transformation: updates VM table state through the session actor boundary.

pub (mut session: Session) set(key: String, value: String): Unit.

/// Threads session response metadata onto a response.
/// Input: one `Response` and one `Session`.
/// Output: a `Response` carrying any required session cookie mutation.
/// Transformation: makes response cookie threading explicit so handler code does
/// not depend on implicit global response state.

pub with_response(response: std.http.Response, session: Session): std.http.Response.

//! Portable server-sent event contract.
//! `std.http.Sse` exposes typed event and endpoint builders for VM-owned
//! `text/event-stream` responses. The runtime owns concrete stream queues,
//! backpressure, and cancellation. The package owns response composition and
//! delegates event framing to its maintained native codec.

module std.http.Sse.

/// Endpoint represents one server-sent event route policy.
/// Input: bounded queue and payload settings.
/// Output: a source-owned endpoint policy validated when a route is admitted.
/// Transformation: keeps live stream state out of source values while allowing
/// route declarations to install explicit SSE endpoint limits.

pub struct Endpoint {
    max_pending_events: Int,
    max_event_bytes: Int,
    keep_alive_ms: Option[Int],
    #response_headers: List[{String, String}],
    #callbacks: List[Callbacks],
    #producers: List[Producer]
}.

/// Event represents one server-sent event payload.
/// Input: optional event metadata plus required UTF-8 data.
/// Output: a source-owned event value with optional metadata.
/// Transformation: hides raw SSE frame construction while preserving typed
/// handler code without allocating a stream or native resource.

pub struct Event {
    id: Option[String],
    event: Option[String],
    retry_ms: Option[Int],
    data: String
}.

/// Installs the complete generated callback set for an endpoint.
/// Input: one endpoint and source callbacks for open, event-ready, keep-alive,
/// graceful drain, and cancellation lifecycle events.
/// Output: the endpoint with one callback set attached.
/// Transformation: retains callbacks as ordinary source values. Repeated sets
/// remain visible for admission to reject; no callback runs during construction.
/// Pull-driven streams await open on first body demand before producing events,
/// and graceful drain before successful EOF. Both callbacks may suspend on VM
/// operations. Cancellation callbacks remain synchronous.

pub (endpoint: Endpoint) callbacks(open: () -> Unit, event_ready: (String) -> Unit, keep_alive: () -> Unit, drain: () -> Unit, cancellation: (String) -> Unit): Endpoint.

/// Creates a data-only SSE event.
/// Input: one UTF-8 event data string.
/// Output: an `Event` with no id, event name, or retry hint.
/// Transformation: constructs an ordinary source record without encoding wire bytes.

@pure
pub data(value: String): Event.

/// Creates an SSE endpoint plan.
/// Input: maximum pending event count and maximum encoded event byte size.
/// Output: an `Endpoint` plan for router lowering.
/// Transformation: records explicit stream bounds for the VM HTTP runtime
/// without allocating a live stream at source evaluation time.

@pure
pub endpoint(max_pending_events: Int = 128, max_event_bytes: Int = 65536): Endpoint.

/// Creates an SSE endpoint plan with keep-alive comments.
/// Input: maximum pending event count, maximum encoded event byte size, and
/// keep-alive interval in milliseconds.
/// Output: an `Endpoint` plan for router lowering.
/// Transformation: records explicit stream bounds and keep-alive policy for the
/// VM HTTP runtime without exposing host async primitives.

pub endpoint_with_keep_alive(max_pending_events: Int = 128, max_event_bytes: Int = 65536, keep_alive_ms: Int = 15000): Endpoint.

/// Supplies one event per transport pull. None ends the stream gracefully.
/// Input: an endpoint and a callback returning an optional typed event.
/// Output: the endpoint with a pull-driven source producer attached.
/// Transformation: normalizes and frames each event only on transport demand.
/// The callback may suspend on VM-owned operations. It never runs during route
/// construction and only resumes production after the previous frame leaves
/// the package. Independent keep-alive scheduling is not supported by this path.

pub (endpoint: Endpoint) producer(next: () -> Option[Event]): Endpoint.

/// Creates a queued SSE response from already available events.
/// Input: a list of typed `Event` values and an optional HTTP status code.
/// Output: a `Response` with `text/event-stream` semantics.
/// Transformation: gives handlers a deterministic queued response path while
/// live stream mutation remains VM-owned runtime work. CRLF is collapsed before
/// CR normalization, preserving one logical newline before maintained framing.

pub response(events: List[Event], status: Int = 200): std.http.Response.

/// Returns an event after setting its id.
/// Input: one `Event` and one UTF-8 id string.
/// Output: the updated `Event`.
/// Transformation: records id metadata on the source-owned event descriptor
/// while preserving expression-style source code.

pub (event: Event) with_id(id: String): Event.

/// Returns an event after setting its event name.
/// Input: one `Event` and one UTF-8 event name.
/// Output: the updated `Event`.
/// Transformation: records event-name metadata on the source-owned descriptor
/// instead of asking source code to write raw `event:` frame lines.

pub (event: Event) with_name(name: String): Event.

/// Returns an event after setting its retry hint.
/// Input: one `Event` and a reconnect retry delay in milliseconds.
/// Output: the updated `Event`.
/// Transformation: records retry metadata; transport admission validates it before encoding.

pub (event: Event) with_retry_ms(retry_ms: Int): Event.

//! Portable HTTP TLS configuration contract.
//! `std.http.Tls` describes the source-visible TLS configuration shape used by
//! Terlan HTTP servers. Runtime certificate loading, ACME, rustls integration,
//! and certificate cache state belong to the HTTP package's native boundary.
//! Hosts provide project discovery and execution, not TLS mode/cache policy.

module std.http.Tls.

/// Auto represents automatic public certificate management.
/// Input: no value input.
/// Output: atom-backed TLS mode value.
/// Transformation: gives configuration code a stable typed mode without
/// exposing ACME provider internals.

pub type Auto =
    std.core.Atom.Auto.

/// Config represents declarative HTTP TLS configuration.
/// Input: no type parameter.
/// Output: typed configuration record shared by source docs, project manifests,
/// and future runtime validation.
/// Transformation: keeps all optional fields explicit so `terlan.toml`
/// validation can enforce mode-specific requirements without changing the
/// source-visible TLS model.

pub type Config =
    {mode: Mode, domains: List[String], email: Option[String], primary_provider: Option[Provider], fallback_provider: Option[Provider], cert: Option[String], key: Option[String], passphrase_env: Option[String], ca: Option[String], server_name: Option[String], trust_local: Bool}.

/// Internal represents local/internal development certificate management.
/// Input: no value input.
/// Output: atom-backed TLS mode value.
/// Transformation: gives configuration code a stable typed mode for local
/// trust roots and internal CAs.

pub type Internal =
    Atom["internal"].

/// LetsEncrypt represents the Let's Encrypt ACME provider.
/// Input: no value input.
/// Output: atom-backed ACME provider value.
/// Transformation: records provider intent without binding source code to one
/// ACME client implementation.

pub type LetsEncrypt =
    Atom["letsencrypt"].

/// Manual represents explicit certificate and key file configuration.
/// Input: no value input.
/// Output: atom-backed TLS mode value.
/// Transformation: gives configuration code a stable typed mode for
/// user-managed certificate files.

pub type Manual =
    std.core.Atom.Manual.

/// Mode represents the supported TLS configuration modes.
/// Input: no type parameter.
/// Output: one of the supported TLS mode atoms.
/// Transformation: narrows server TLS configuration to the roadmap-approved
/// modes before target-specific validation runs.

pub type Mode =
    Auto
  | Manual
  | Internal.

/// Provider represents the public ACME providers supported by 0.0.5 planning.
/// Input: no type parameter.
/// Output: one of the supported provider atoms.
/// Transformation: narrows provider names before manifest and runtime
/// validation choose the concrete Rust ACME integration.

pub type Provider =
    LetsEncrypt
  | ZeroSsl.

/// ZeroSsl represents the ZeroSSL ACME provider.
/// Input: no value input.
/// Output: atom-backed ACME provider value.
/// Transformation: records fallback provider intent without binding source
/// code to one ACME client implementation.

pub type ZeroSsl =
    Atom["zerossl"].

/// Builds automatic public TLS configuration.
/// Input: one domain list and one ACME account email address.
/// Output: a `Config` value using automatic public certificate management.
/// Transformation: fills the public ACME provider defaults while leaving
/// manual certificate fields empty so manifest validation can focus on
/// deployment-specific requirements.

pub auto(domains: List[String], email: String): Config.

/// Builds local/internal TLS configuration.
/// Input: one local server name.
/// Output: a `Config` value using internal development certificate handling.
/// Transformation: records the intended local server identity and marks the
/// config as locally trusted while leaving public ACME and manual certificate
/// file settings empty.

pub internal(server_name: String): Config.

/// Builds manual certificate TLS configuration.
/// Input: one certificate path and one private-key path.
/// Output: a `Config` value using user-managed certificate files.
/// Transformation: records explicit certificate paths while leaving ACME and
/// local trust settings empty.

pub manual(cert: String, key: String): Config.

//! Portable WebSocket channel contract.
//! `std.http.WebSocket` exposes typed frame and endpoint builders for
//! VM-owned WebSocket channels. The runtime owns socket lifecycle, frame
//! parsing, backpressure, cancellation, and handler scheduling.

module std.http.WebSocket.

/// CloseFrame represents a request to close the channel.
/// Input: none.
/// Output: a singleton close intent.
/// Transformation: separates close intent from transport lifecycle execution.

pub type CloseFrame =
    Atom["close"].

/// Endpoint represents one WebSocket route policy.
/// Input: inbound queue and frame-size settings.
/// Output: a source-owned endpoint policy validated when a route is admitted.
/// Transformation: keeps live connection state out of source values while
/// allowing route declarations to install explicit WebSocket limits.

pub struct Endpoint {
    max_pending_frames: Int,
    max_frame_bytes: Int,
    #policies: List[Policy]
}.

/// Frame is an outbound text or control-frame intent.
/// Input: a text, ping, pong, or close value.
/// Output: a source-owned discriminated union.
/// Transformation: permits ordinary pattern matching without native handles.

pub type Frame =
    TextFrame
  | PingFrame
  | PongFrame
  | CloseFrame.

/// PingFrame carries an outbound heartbeat payload.
/// Input: one UTF-8 payload.
/// Output: a source-owned tagged control-frame value.
/// Transformation: records intent; transport admission validates byte limits.

pub type PingFrame =
    {Atom["ping"], value: String}.

/// PongFrame carries an outbound heartbeat response.
/// Input: one UTF-8 payload.
/// Output: a source-owned tagged control-frame value.
/// Transformation: preserves payload bytes without performing socket I/O.

pub type PongFrame =
    {Atom["pong"], value: String}.

/// TextFrame carries one outbound WebSocket text payload.
/// Input: typed text or control-frame metadata.
/// Output: a source-owned tagged text-frame value.
/// Transformation: hides raw WebSocket frame bytes while preserving typed
/// handler code without allocating a connection or native resource.

pub type TextFrame =
    {Atom["text"], value: String}.

/// Installs the complete generated callback set for an endpoint.
/// Input: one endpoint and source callbacks for open, inbound frame, writable,
/// graceful close, and cancellation lifecycle events.
/// Output: the endpoint with one callback set attached.
/// Transformation: retains callbacks as ordinary source values without invoking
/// them. Duplicate/conflicting declarations remain visible to route admission.
/// Open, inbound, writable, and graceful-close callbacks may wait on VM timers
/// and native work. Inbound and writable callbacks may also retain a text receive
/// for the next frame; writable notifications never replace a parked callback.
/// Cancellation notifications must complete without waiting.

pub (endpoint: Endpoint) callbacks(open: () -> Unit, inbound: (String) -> Unit, writable: () -> Unit, close: () -> Unit, cancellation: (String) -> Unit): Endpoint.

/// Creates an outbound close control frame.
/// Input: none.
/// Output: a `Frame` with close control semantics.
/// Transformation: records deterministic close intent while stream shutdown and
/// cleanup remain VM-owned runtime behavior.

@pure
pub close(): Frame.

/// Creates a WebSocket endpoint plan.
/// Input: maximum pending inbound frame count and maximum accepted frame bytes.
/// Output: an `Endpoint` plan for router lowering.
/// Transformation: records explicit channel bounds for the VM HTTP runtime
/// without allocating a live socket at source evaluation time.

@pure
pub endpoint(max_pending_frames: Int = 128, max_frame_bytes: Int = 65536): Endpoint.

/// Installs a two-peer session policy with source-owned protocol payloads.
/// The runtime queues the waiting payload for the first peer, delivers the two
/// role-specific match payloads when a second peer arrives, and notifies the
/// remaining peer when a connection closes. The source adapter invokes each
/// inbound callback once and selects both peer deliveries, including empty
/// frames. Before pairing or after disconnect, it replies to the remaining peer.

pub (endpoint: Endpoint) paired_callbacks(waiting: String, first_matched: String, second_matched: String, peer_left: String, inbound: (String) -> String, cancellation: (String) -> Unit): Endpoint.

/// Creates an outbound ping control frame.
/// Input: one UTF-8 ping payload.
/// Output: a `Frame` with ping control semantics.
/// Transformation: records typed ping intent while the VM runtime owns wire
