/// Output: a table result report for the remaining iterator values.
/// Transformation: public implementation helper for VM std execution paths
/// that currently load public std functions only.

pub each_result_report_iterator[T, E](iterator: std.collections.Iterator[Row[T, E]], index: Int, actual: (T) -> E): TableResultReport[E].

/// Returns a failing assertion result.
/// Input: no arguments.
/// Output: always `false`.
/// Transformation: returns the portable failing assertion value directly.

@pure
pub fail(): Assertion.

/// Runs one explicit lifecycle and returns the combined assertion result.
/// Input: seed value, setup callbacks, body callback, and cleanup callbacks.
/// Output: `true` only when body and both cleanup callbacks return `true`.
/// Transformation: delegates to `lifecycle_result` and combines the three
/// observable outcomes without hiding cleanup failures.

pub lifecycle[Seed, Suite, Fixture](seed: Seed, before_all: (Seed) -> Suite, before_each: (Suite) -> Fixture, body: (Fixture) -> Assertion, after_each: (Fixture) -> Assertion, after_all: (Suite) -> Assertion): Assertion.

/// Runs one explicit lifecycle and returns every observable outcome.
/// Input: seed value, setup callbacks, body callback, and cleanup callbacks.
/// Output: `{body_result, after_each_result, after_all_result}`.
/// Transformation: runs `before_all`, then `before_each`, then `body`, then
/// `after_each`, then `after_all`. Cleanup callbacks run even when `body`
/// returns `false` because the results are collected independently.

pub lifecycle_result[Seed, Suite, Fixture](seed: Seed, before_all: (Seed) -> Suite, before_each: (Suite) -> Fixture, body: (Fixture) -> Assertion, after_each: (Fixture) -> Assertion, after_all: (Suite) -> Assertion): LifecycleResult.

/// Constructs one named table row.
/// Input: row name, input value, and expected value.
/// Output: a `Row[T, E]`.
/// Transformation: stores test data as an ordinary tuple value.

@pure
pub row[T, E](name: Binary, input: T, expected: E): Row[T, E].

/// Runs lifecycle hooks across table rows and returns one assertion.
/// Input: seed value, table rows, setup callbacks, body callback, and cleanup
/// callbacks.
/// Output: `true` only when every row body, every per-row cleanup, and final
/// cleanup pass.
/// Transformation: delegates to `table_lifecycle_result` and combines the
/// observable outcomes without hiding cleanup failures.

pub table_lifecycle[Seed, Item, Suite, Fixture](seed: Seed, rows: List[Item], before_all: (Seed) -> Suite, before_each: (Suite, Item) -> Fixture, body: (Fixture) -> Assertion, after_each: (Fixture) -> Assertion, after_all: (Suite) -> Assertion): Assertion.

/// Runs lifecycle hooks across table rows and returns observable outcomes.
/// Input: seed value, table rows, setup callbacks, body callback, and cleanup
/// callbacks.
/// Output: `{body_result, after_each_result, after_all_result}`.
/// Transformation: runs `before_all` once, then `before_each`, `body`, and
/// `after_each` for every row, then `after_all` once. Per-row cleanup is
/// evaluated even when a row body fails.

pub table_lifecycle_result[Seed, Item, Suite, Fixture](seed: Seed, rows: List[Item], before_all: (Seed) -> Suite, before_each: (Suite, Item) -> Fixture, body: (Fixture) -> Assertion, after_each: (Fixture) -> Assertion, after_all: (Suite) -> Assertion): LifecycleResult.

/// Runs per-row lifecycle callbacks for every table row.
/// Input: rows, suite fixture, per-row setup callback, body callback, and
/// per-row cleanup callback.
/// Output: `{all_body_results, all_after_each_results}`.
/// Transformation: public implementation helper for VM std execution paths
/// that currently load public std functions only.

pub table_lifecycle_rows[Item, Suite, Fixture](rows: List[Item], suite: Suite, before_each: (Suite, Item) -> Fixture, body: (Fixture) -> Assertion, after_each: (Fixture) -> Assertion): {Assertion, Assertion}.

/// Reduces table lifecycle rows with explicit assertion accumulators.
/// Input: remaining rows, callbacks, and accumulated body and cleanup results.
/// Output: the combined body and cleanup assertion results.
/// Transformation: uses tail recursion so a suspension-capable callback never
/// retains an unbounded native caller stack while later rows execute.

pub table_lifecycle_rows_at[Item, Suite, Fixture](rows: List[Item], suite: Suite, before_each: (Suite, Item) -> Fixture, body: (Fixture) -> Assertion, after_each: (Fixture) -> Assertion, body_accumulator: Assertion, after_each_accumulator: Assertion): {Assertion, Assertion}.

