//! Terlan VM byte buffer contract.
//! `std.vm.Bytes` represents binary protocol frames owned by the runtime target.
//! It is intentionally target-specific so daemon and socket tests can exchange
//! exact byte sequences without adding byte-array syntax to portable Terlan.

module std.vm.Bytes.

/// Byte is an integer interpreted as one unsigned octet.
/// Input: no runtime input.
/// Output: an `Int` value constrained by this module's constructors and
/// operations to the range `0..255`.
/// Transformation: names the protocol-byte intent without creating a new
/// portable numeric primitive.

pub type Byte =
    Int.

/// Bytes represents a runtime-owned binary byte buffer.
/// Input: no runtime input.
/// Output: an opaque target-owned byte buffer handle.
/// Transformation: keeps runtime binary representation behind the selected VM
/// contract while exposing a typed protocol-frame value in Terlan source.

pub opaque type Bytes.

/// Concatenates two byte buffers.
/// Input: two `Bytes` values.
/// Output: a new buffer with `left` followed by `right`.
/// Transformation: asks the selected VM runtime to join binary buffers without copying
/// byte lists through portable collection code.

@pure
pub concat(left: Bytes, right: Bytes): Bytes.

/// Returns whether this buffer contains the complete needle buffer.

@pure
pub (bytes: Bytes) contains(needle: Bytes): Bool.

/// Returns the first non-ASCII-whitespace byte index, or `-1` when absent.

@pure
pub (bytes: Bytes) first_non_ascii_whitespace(): Int.

/// Builds a byte buffer from unsigned octets.
/// Input: one list of byte values.
/// Output: `Bytes` containing the values in source order.
/// Transformation: asks the selected VM runtime to validate each octet and pack
/// the values into a binary protocol frame.

@pure
pub from_list(values: List[Byte]): Bytes.

/// Returns the byte length of a buffer.
/// Input: one `Bytes` receiver.
/// Output: count of octets in the buffer.
/// Transformation: delegates to the runtime binary size operation while preserving
/// the opaque source-level representation.

@pure
pub (bytes: Bytes) length(): Int.

/// Reads one signed big-endian integer from an arbitrary bit range.
/// Input: a byte buffer, a zero-based bit offset measured from the most
/// significant bit of the first byte, and a bit width in `1..63`.
/// Output: the selected bits interpreted as a two's-complement Terlan `Int`.
/// Transformation: validates and accumulates the complete bit range in network
/// order before sign-extending the declared width.

pub (bytes: Bytes) read_int_be(bit_offset: Int, bit_width: Int): Int.

/// Reads one signed little-endian integer from an arbitrary bit range.
/// Input: a byte buffer, a zero-based bit offset measured from the most
/// significant bit of the first byte, and a bit width in `1..63`.
/// Output: the selected little-endian groups interpreted as a two's-complement
/// Terlan `Int`.
/// Transformation: accumulates successive groups from least to most
/// significant before sign-extending the declared width.

pub (bytes: Bytes) read_int_le(bit_offset: Int, bit_width: Int): Int.

/// Reads one unsigned big-endian integer from an arbitrary bit range.
/// Input: a byte buffer, a zero-based bit offset measured from the most
/// significant bit of the first byte, and a bit width in `1..63`.
/// Output: the selected bits as a non-negative Terlan `Int`.
/// Transformation: validates the complete bit range before accumulating bits in
/// network order without exposing host pointers or backend bit syntax.

pub (bytes: Bytes) read_uint_be(bit_offset: Int, bit_width: Int): Int.

/// Reads one unsigned little-endian integer from an arbitrary bit range.
/// Input: a byte buffer, a zero-based bit offset measured from the most
/// significant bit of the first byte, and a bit width in `1..63`.
/// Output: the selected bits as a non-negative Terlan `Int`.
/// Transformation: reads network-order bits in groups of at most eight and
/// assigns each successive group increasing numeric significance.

pub (bytes: Bytes) read_uint_le(bit_offset: Int, bit_width: Int): Int.

/// Extracts an immutable byte range.
/// Input: a byte buffer, a zero-based start offset, and a byte length.
/// Output: a new `Bytes` value containing exactly the selected octets.
/// Transformation: validates the complete range before copying the selected
/// bytes into VM-owned immutable storage.

pub (bytes: Bytes) slice(start: Int, length: Int): Bytes.

/// Returns whether this buffer begins with the complete prefix buffer.

@pure
pub (bytes: Bytes) starts_with(prefix: Bytes): Bool.

/// Returns a byte buffer as unsigned octets.
/// Input: one `Bytes` receiver.
/// Output: the byte values in buffer order.
/// Transformation: asks the selected VM runtime to unpack the binary into a
/// typed Terlan list without exposing backend bit syntax.

@pure
pub (bytes: Bytes) to_list(): List[Byte].

//! Terlan VM cluster coordination contract.
//! `std.vm.Cluster` exposes the first typed source-level surface for VM-owned
//! distributed node coordination. It models profiles, membership views, and
//! transport sessions as ordinary VM descriptors while the VM owns protocol
//! framing, delivery classification, and lifecycle checks.
//! Bootstrap is explicit: each VM starts from its local `Profile`, creates a
//! `Membership`, and joins compatible seed profiles learned from deployment
//! configuration or an authenticated transport. Seeds are discovery inputs,
//! not permanent leaders or consensus authorities. Identity, cluster id,
//! runtime version, capability, and epoch checks remain mandatory for every
//! joined peer.
//! Rolling restart preserves stable application, VM, and node identity while
//! advancing the incarnation with `Profile.next_epoch`. A peer first becomes
//! unreachable, then `Membership.restart` admits only the strictly newer,
//! compatible, unfenced profile and preserves its declared roles. Leadership
//! hints are deterministic routing hints over active role tags; they are not a
//! consensus or replicated-state guarantee.
//! Native AOT executes profiles, membership, and in-memory transport sessions.
//! Updates produce immutable actor-owned snapshots. Frames use the VM's TETF
//! codec and the admitted image's atom vocabulary; no operation here discovers
//! peers or opens network connections. Scalar, byte/string, record, list, and
//! tuple, Map, Set, and Binary bitstring payloads are supported. Actor-local
//! handles are rejected. VM-owned calls preserve typed values directly;
//! external workers retain their separate, narrower wire vocabulary.

module std.vm.Cluster.

/// AcceptResult carries delivery classification and the advanced session.
/// Transformation: preserves duplicate and ordering history without relying on
/// process-global mutable transport state.

pub struct AcceptResult {
    session: Session,
    outcome: InboundOutcome
}.

/// Accepted identifies a frame consumed in the expected message order.

pub type Accepted =
    Atom["accepted"].

/// AcknowledgeResult carries the advanced session and acknowledged message id.

pub struct AcknowledgeResult {
    session: Session,
    message_id: Int
}.

/// Active identifies a node currently eligible for cluster work.

pub type Active =
    Atom["active"].

/// AlreadyConnected identifies a reconnect request that required no transition.

pub type AlreadyConnected =
    Atom["already_connected"].

/// AtMostOnce sends a frame without retaining acknowledgement state.

pub type AtMostOnce =
    Atom["at_most_once"].

/// ClusterHealth is the closed aggregate membership health domain.

pub type ClusterHealth =
    Healthy
  | Degraded.

/// Connected identifies a transport session that permits message operations.

pub type Connected =
    Atom["connected"].

/// Degraded identifies a membership view containing any non-active node.

pub type Degraded =
    Atom["degraded"].

/// Delivery is the closed distributed message-delivery policy domain.

pub type Delivery =
    AtMostOnce
  | NeedsAck.

/// DisconnectEvent is the inspectable result of closing one session.

pub struct DisconnectEvent {
    reason: DisconnectReason,
    tick: Int,
    pending_ack_count: Int
}.

/// DisconnectReason is the closed transport shutdown reason domain.

pub type DisconnectReason =
    LocalClose
  | RemoteClose
  | TransportFailure
  | HeartbeatTimeout
  | SessionFenced.

/// DisconnectResult carries an advanced session and its disconnect event.

pub struct DisconnectResult {
    session: Session,
    event: DisconnectEvent
}.

/// Disconnected identifies a transport session waiting for reconnection.

pub type Disconnected =
    Atom["disconnected"].

/// Duplicate identifies a frame whose message was already consumed.

pub type Duplicate =
    Atom["duplicate"].

/// Fenced identifies a node identity prohibited from rejoining.

pub type Fenced =
    Atom["fenced"].

/// Frame represents one encoded distributed transport frame.
/// Input: produced by a VM transport session.
/// Output: an opaque frame descriptor addressed between two VM nodes.
/// Transformation: preserves encoded payload and message identity so the remote
/// session can classify delivery deterministically.

pub opaque type Frame.

/// Healthy identifies a membership view where every known node is active.

pub type Healthy =
    Atom["healthy"].

/// HeartbeatTimeout identifies a session closed after peer liveness expiry.

pub type HeartbeatTimeout =
    Atom["heartbeat_timeout"].

/// InboundOutcome is the closed inbound delivery classification domain.

pub type InboundOutcome =
    Accepted
  | Duplicate
  | OutOfOrder.

/// Left identifies a node that departed intentionally.

pub type Left =
    std.core.Atom.Left.

/// LocalClose identifies an intentional local session shutdown.

pub type LocalClose =
    Atom["local_close"].

/// Membership represents a deterministic cluster membership view.
/// Input: one local profile plus heartbeat policy.
/// Output: an opaque membership descriptor with VM-owned node states.
/// Transformation: records node lifecycle transitions without embedding
/// consensus or network transport in user source.

pub opaque type Membership.

/// Missing identifies a node absent from the membership view.

pub type Missing =
    Atom["missing"].

/// NeedsAck retains a frame id until the session records its acknowledgement.

pub type NeedsAck =
    Atom["needs_ack"].

/// Node is one inspectable entry in a deterministic membership view.
/// Input: produced by `Membership.view`.
/// Output: node identity, typed lifecycle state, last observed VM tick, and
/// sorted role tags.
/// Transformation: exposes stable cluster metadata without exposing the VM's
/// internal membership table or transport handles.

pub struct Node {
    node_id: String,
    state: NodeState,
    last_seen_tick: Int,
    roles: List[String]
}.

/// NodeState is the closed source-level cluster lifecycle domain.
/// Input: produced by membership inspection.
/// Output: exactly one lifecycle singleton.
/// Transformation: keeps exhaustive source matching aligned with the VM-owned
/// `VmClusterNodeState` state machine while representing an absent lookup
/// explicitly as `Missing`.

pub type NodeState =
    Active
  | Left
  | Unreachable
  | Fenced
  | Missing.

/// OutOfOrder identifies a frame received before its predecessor.
/// Input: produced by `Session.accept`.
/// Output: the next message id required by the session.
/// Transformation: keeps ordering diagnostics typed and preserves the session
/// so the missing frame can be accepted before retrying.

pub struct OutOfOrder {
    expected_message_id: Int
}.

/// Profile represents one VM node identity in a cluster.
/// Input: application, VM, node, cluster, runtime version, and capability names.
/// Output: an opaque coordination profile.
/// Transformation: keeps identity and compatibility checks in the VM while
/// allowing Terlan source to describe a two-node cluster scenario.

pub opaque type Profile.

/// ReconnectOutcome is the closed reconnect classification domain.

pub type ReconnectOutcome =
    AlreadyConnected
  | Reconnected.

/// ReconnectResult carries an advanced session and typed reconnect outcome.

pub struct ReconnectResult {
    session: Session,
    outcome: ReconnectOutcome
}.

/// Reconnected identifies a successful disconnected-to-connected transition.

pub struct Reconnected {
    pending_ack_count: Int
}.

/// RemoteClose identifies an intentional remote session shutdown.

pub type RemoteClose =
    Atom["remote_close"].

/// SendResult carries an encoded frame and the advanced outbound session.
/// Transformation: makes immutable session rebinding explicit so message ids
/// remain monotonic across successive source-level sends.

pub struct SendResult {
    session: Session,
    frame: Frame
}.

/// Session represents a bounded distributed transport session.
/// Input: local and remote profiles plus a maximum message size.
/// Output: an opaque transport session descriptor.
/// Transformation: gives source-level tests a VM-owned transport path without
/// exposing socket, scheduler, or wire-format internals.

pub opaque type Session.

/// SessionFenced identifies a session closed by node fencing policy.

pub type SessionFenced =
    Atom["session_fenced"].

/// SessionState is the closed transport lifecycle state domain.

pub type SessionState =
    Connected
  | Disconnected.

/// TransportFailure identifies an underlying transport failure.

pub type TransportFailure =
    Atom["transport_failure"].

/// Unreachable identifies a node whose heartbeat deadline expired.

pub type Unreachable =
    Atom["unreachable"].

/// Accepts one inbound frame on a session.
/// Input: session receiver and frame descriptor.
/// Output: advanced session plus `Accepted`, `Duplicate`, or `OutOfOrder`.
/// Transformation: delegates delivery classification to the VM distributed
/// transport session.

pub (session: Session) accept(frame: Frame): AcceptResult.

/// Records one outbound frame acknowledgement.
/// Input: session receiver and a frame emitted by that session.
/// Output: advanced session and the acknowledged message id.
/// Transformation: validates frame ownership and removes exactly one pending id;
/// duplicate or unrelated acknowledgements fail with a stable VM diagnostic.

pub (session: Session) acknowledge(frame: Frame): AcknowledgeResult.

/// Returns the closed delivery policy encoded in one frame.

pub (frame: Frame) delivery(): Delivery.

/// Disconnects one transport session with an inspectable typed reason.
/// Input: session receiver, typed reason, and monotonic VM tick.
/// Output: advanced disconnected session and its immutable event.
/// Transformation: preserves pending acknowledgement state while the VM blocks
/// message operations until a valid reconnect.

pub (session: Session) disconnect(reason: DisconnectReason, tick: Int): DisconnectResult.

/// Returns the positive restart epoch carried by one profile.

pub (profile: Profile) epoch(): Int.

/// Applies heartbeat timeout policy to the membership view.
/// Input: membership receiver and current monotonic VM tick.
/// Output: updated membership descriptor with stale peers unreachable.
/// Transformation: preserves the exact VM timeout boundary while leaving the
/// local node active and retaining peer identity for later recovery.

pub (membership: Membership) expire(current_tick: Int): Membership.

/// Fences one known peer identity.
/// Input: membership receiver, peer node id, and monotonic VM tick.
/// Output: updated membership descriptor with the peer in `fenced` state.
/// Transformation: prevents the same peer identity from rejoining and makes
/// administrative isolation explicit in source-level cluster control.

pub (membership: Membership) fence(node_id: String, tick: Int): Membership.

/// Heals one unreachable peer.
/// Input: membership receiver, peer node id, and monotonic VM tick.
/// Output: updated membership with the peer `Active`.
/// Transformation: accepts only an unreachable peer and preserves identity,
/// epoch, and role tags across the simulated partition interval.

pub (membership: Membership) heal(node_id: String, tick: Int): Membership.

/// Returns aggregate membership health.
/// Input: one membership receiver.
/// Output: `Healthy` when every node is active, otherwise `Degraded`.
/// Transformation: derives health only from typed membership state.

pub (membership: Membership) health(): ClusterHealth.

/// Records a heartbeat for one known peer.
/// Input: membership receiver, peer node id, and monotonic VM tick.
/// Output: updated membership descriptor with the peer active.
/// Transformation: rejects stale or ineligible heartbeats through the same
/// VM-owned membership state machine used by distributed scheduling.

pub (membership: Membership) heartbeat(node_id: String, tick: Int): Membership.

/// Adds a compatible peer to the membership view.
/// Input: membership receiver, peer profile, VM tick, and role tag.
/// Output: updated membership descriptor.
/// Transformation: applies VM-owned compatibility and role-tag ordering rules.

pub (membership: Membership) join(peer: Profile, tick: Int, role: String): Membership.

/// Returns a deterministic active leadership hint.
/// Input: one membership receiver.
/// Output: the first active node tagged `leader`, ordered by node id, or `None`.
/// Transformation: exposes a routing hint only; it does not implement consensus
/// or claim authoritative leadership.

pub (membership: Membership) leader_hint(): Option[String].

/// Marks one known peer as intentionally departed.
/// Input: membership receiver, peer node id, and monotonic VM tick.
/// Output: updated membership descriptor with the peer in `left` state.
/// Transformation: distinguishes an orderly departure from heartbeat failure
/// while preserving the peer snapshot for deterministic diagnostics.

pub (membership: Membership) leave(node_id: String, tick: Int): Membership.

/// Creates a membership view rooted at a local profile.
/// Input: local profile and non-zero heartbeat timeout in VM ticks.
/// Output: membership descriptor containing the local node as active.
/// Transformation: validates membership policy through the VM coordination
/// layer before source code can join peers.

pub membership(local: Profile, heartbeat_timeout_ticks: Int): Membership.

/// Returns the stable message id assigned to one frame.

pub (frame: Frame) message_id(): Int.

/// Returns whether one outbound frame still requires acknowledgement.

pub (session: Session) needs_ack(frame: Frame): Bool.

/// Advances a profile to its next node incarnation.
/// Input: one profile receiver.
/// Output: the same stable identity with a strictly newer epoch.
/// Transformation: provides explicit rolling-restart identity without changing
/// application, VM, node, cluster, runtime, or capability metadata.

pub (profile: Profile) next_epoch(): Profile.

/// Returns the explicit node identity stored in a profile.
/// Input: one validated `Profile` receiver.
/// Output: the profile's node id.
/// Transformation: reads VM-owned coordination metadata without consulting
/// process-global state or synthesizing an implicit local node name.

pub (profile: Profile) node_id(): String.

/// Opens a bounded transport session.
/// Input: local profile, remote profile, and maximum encoded message bytes.
/// Output: session descriptor.
/// Transformation: validates profile compatibility and message-size policy
/// through the VM distributed transport layer.

pub open(local: Profile, remote: Profile, max_message_bytes: Int): Session.

/// Simulates loss of connectivity to one active peer.
/// Input: membership receiver, peer node id, and monotonic VM tick.
/// Output: updated membership with the peer `Unreachable`.
/// Transformation: keeps identity and role metadata while making partition
/// behavior deterministic and observable to placement and failover policy.

pub (membership: Membership) partition(node_id: String, tick: Int): Membership.

/// Returns the number of outstanding acknowledgements retained by the session.

pub (session: Session) pending_ack_count(): Int.

/// Builds one VM coordination profile.
/// Input: application id, VM id, node id, cluster id, runtime version, and one
/// advertised capability.
/// Output: a profile descriptor.
/// Transformation: normalizes the minimum identity tuple required to open a
/// VM-owned distributed transport session.

pub profile(app_id: String, vm_id: String, node_id: String, cluster_id: String, runtime_version: String, capability: String): Profile.

/// Prunes stale departed or unreachable peer snapshots after a retention window.
/// Input: membership receiver, current monotonic VM tick, and non-zero retention
/// ticks.
/// Output: updated membership descriptor without expired terminal snapshots.
/// Transformation: retains the local node plus every active and fenced identity;
/// pruning occurs only after the exact retention boundary has passed.

pub (membership: Membership) prune(current_tick: Int, retention_ticks: Int): Membership.

/// Reconnects one transport session to its original compatible remote profile.
/// Input: session receiver, remote profile, and monotonic VM tick.
/// Output: advanced session and `AlreadyConnected` or `Reconnected` outcome.
/// Transformation: validates stable remote identity and retains transport
/// continuity state across the disconnected interval.

pub (session: Session) reconnect(remote: Profile, tick: Int): ReconnectResult.

/// Replaces one known peer with a strictly newer profile incarnation.
/// Input: membership receiver, same peer identity at a newer epoch, and VM tick.
/// Output: updated membership with the peer active and its roles preserved.
/// Transformation: rejects stale, unknown, mismatched, incompatible, or fenced
/// identities before replacing restart state.

pub (membership: Membership) restart(peer: Profile, tick: Int): Membership.

/// Sends one at-most-once message frame.
/// Input: session receiver, target capability, and typed payload.
/// Output: encoded frame descriptor plus the advanced session.
/// Transformation: uses the VM distributed transport session to assign message
/// identity, validate target capability, and produce a bounded frame.

pub (session: Session) send[Payload]<SendAcrossNode[Payload]>(capability: String, payload: Payload): SendResult.

/// Sends one message with an explicit closed delivery policy.
/// Input: session receiver, target capability, typed payload, and delivery
/// policy.
/// Output: encoded frame descriptor plus the advanced session.
/// Transformation: `NeedsAck` retains the frame message id in the VM-owned
/// session snapshot until `acknowledge` consumes it.

pub (session: Session) send_with[Payload]<SendAcrossNode[Payload]>(capability: String, payload: Payload, delivery: Delivery): SendResult.

/// Returns the current transport session lifecycle state.
/// Input: one session receiver.
/// Output: `Connected` or `Disconnected`.
/// Transformation: exposes lifecycle state without leaking descriptor fields.

pub (session: Session) state(): SessionState.

/// Reads the current state for one node.
/// Input: membership receiver and node id.
/// Output: `Active`, `Left`, `Unreachable`, `Fenced`, or `Missing`.
/// Transformation: exposes a closed lifecycle domain without leaking the
/// internal membership table representation.

pub (membership: Membership) state(node_id: String): NodeState.

/// Returns all known nodes in deterministic node-id order.
/// Input: one membership receiver.
/// Output: typed node snapshots including the local node.
/// Transformation: projects the VM-owned ordered membership view into ordinary
/// immutable Terlan records.

pub (membership: Membership) view(): List[Node].

/// SendAcrossNode marks payloads that may cross a VM cluster boundary.
/// Input: distributed payload type `T`.
/// Output: an identity proof method used by generic node transport boundaries.
/// Transformation: lets ordinary values use the default transport encoding
/// while allowing a concrete `impl not SendAcrossNode[LocalType]` declaration
/// to prohibit cross-node delivery at compile time.

pub trait SendAcrossNode[T] {
    transfer(value: T): T.
}.

pub impl SendAcrossNode[T] for T {
}.

//! Terlan VM distributed state contract.
//! `std.vm.DistributedState` exposes typed descriptors for VM-owned state
//! scopes, monotonic versions, conflict policies, write outcomes, and
//! checkpoint snapshots. The VM owns deterministic conflict handling and
//! checkpoint replay within the execution shard. Stores are actor-owned and
//! mutable; snapshots and entry/outcome descriptors are immutable views.
//! This module does not replicate data to peers or persist checkpoints to disk.
//! Only last-writer-wins replaces a conflicting entry automatically; other
//! policies return a conflict for explicit resolution, including `merge`.

module std.vm.DistributedState.

/// Conflict represents a deterministic write conflict.
/// Input: local and incoming versions plus policy metadata.
/// Output: an opaque conflict descriptor.
/// Transformation: preserves enough typed metadata for callers to resolve the
/// conflict without parsing diagnostics.

pub opaque type Conflict.

/// Entry represents one stored distributed state value.
/// Input: scope, owner, value, version, and policy.
/// Output: an opaque state entry descriptor.
/// Transformation: gives source and tooling a typed entry handle without
/// exposing the runtime table representation.

pub opaque type Entry.

/// Outcome represents one distributed write result.
/// Input: store write operation.
/// Output: applied, replayed, conflict, or policy-mismatch descriptor.
/// Transformation: avoids undefined behavior by making every write result
/// explicit at the Terlan boundary.

pub opaque type Outcome.

/// Policy represents one distributed conflict strategy.
/// Input: policy tag such as `winner_takes_all`, `last_writer_wins`, `merge`,
/// or `explicit_user_resolution`.
/// Output: an opaque policy descriptor.
/// Transformation: keeps strategy validation and unsupported behavior explicit.

pub opaque type Policy.

/// Scope represents one namespaced distributed state key.
/// Input: namespace and key text.
/// Output: an opaque state scope descriptor.
/// Transformation: keeps namespace/key validation inside the VM distributed
/// state lane.

pub opaque type Scope.

/// Snapshot represents one deterministic checkpoint.
/// Input: a VM-owned distributed state store.
/// Output: an opaque checkpoint descriptor.
/// Transformation: keeps checkpoint ordering and replay validation in the VM.

pub opaque type Snapshot.

/// Store represents one VM-owned distributed state table.
/// Input: write operations and checkpoint restore descriptors.
/// Output: an opaque state store descriptor.
/// Transformation: owns state entries, conflict metadata, and checkpoint replay
/// ordering inside the VM.

pub opaque type Store.

/// Version represents one monotonic write version.
/// Input: sequence number and writer node id.
/// Output: an opaque state version descriptor.
/// Transformation: keeps version monotonicity and writer identity validation in
/// the VM runtime.

pub opaque type Version.

/// Extracts conflict metadata from a write outcome.
/// Input: outcome descriptor.
/// Output: conflict descriptor.
/// Transformation: exposes local/incoming version metadata for explicit caller
/// resolution.

pub conflict(outcome: Outcome): Conflict.

/// Returns the rejected write sequence captured when a conflict occurred.

pub conflict_incoming_sequence(conflict: Conflict): Int.

/// Returns the existing write sequence captured when a conflict occurred.

pub conflict_local_sequence(conflict: Conflict): Int.

/// Returns the owner node recorded in an immutable entry view.

pub entry_owner(entry: Entry): String.

/// Returns the write sequence recorded in an immutable entry view.

pub entry_sequence(entry: Entry): Int.

/// Exports a deterministic checkpoint snapshot.
/// Input: store receiver.
/// Output: snapshot descriptor.
/// Transformation: delegates stable ordering to the VM checkpoint lane.

pub (store: Store) export_snapshot(): Snapshot.

/// Reads one distributed state entry.
/// Input: store receiver and scope descriptor.
/// Output: entry descriptor.
/// Transformation: keeps the lookup result typed without exposing runtime map
/// internals.

pub (store: Store) get(scope: Scope): Entry.

/// Returns the textual write outcome kind.
/// Input: outcome descriptor.
/// Output: `applied`, `replayed`, `conflict`, or `policy_mismatch`.
/// Transformation: exposes stable result classification for tests, logs, and
/// tooling without parsing diagnostics.

pub kind(outcome: Outcome): String.

/// Builds a conflict policy descriptor.
/// Input: policy tag.
/// Output: policy descriptor.
/// Transformation: normalizes source policy names to VM-owned conflict
/// strategies.

pub policy(name: String): Policy.

/// Restores a store from a checkpoint snapshot.
/// Input: snapshot descriptor.
/// Output: restored store descriptor.
/// Transformation: validates duplicate scopes and version metadata during VM
/// checkpoint replay.

pub restore(snapshot: Snapshot): Store.

/// Builds a state scope descriptor.
/// Input: namespace and key.
/// Output: scope descriptor.
/// Transformation: validates non-empty namespace and key through the VM state
/// contract.

pub scope(namespace: String, key: String): Scope.

/// Creates an empty distributed state store.
/// Input: no runtime input.
/// Output: store descriptor.
/// Transformation: creates a VM-owned table with no implicit backend or
/// replication strategy.

pub store(): Store.

/// Builds a state version descriptor.
/// Input: non-zero sequence and writer node id.
/// Output: version descriptor.
/// Transformation: validates monotonic write metadata through the VM state
/// contract.

pub version(sequence: Int, node_id: String): Version.

/// Writes one distributed state value.
/// Input: store receiver, scope, owner node, checked value, version, and policy.
/// Output: write outcome descriptor.
/// Transformation: delegates apply/replay/conflict/policy-mismatch behavior to
/// the VM distributed state lane.

pub (store: Store) write[Value](scope: Scope, owner_node_id: String, value: Value, version: Version, policy: Policy): Outcome.

//! Terlan VM distributed storage adapter contract.
//! `std.vm.DistributedStorage` exposes typed descriptors for VM-owned
//! checkpoint storage adapters. `checkpoint` and `Snapshot.restore` capture and
//! restore bounded, versioned logical state. The standalone VM connects durable
//! `open`, `append`, `flush`, `load_snapshot`, and `close` to a sandboxed SQLite
//! worker through explicit `--storage name=/absolute/private/directory` bindings.
//! Atomic batches, compare-and-swap append, schema transitions, and compaction
//! use the same durable worker. Typed outcomes retain transaction-observed
//! conflicts; proofs require acknowledged durable observations. Policy flags
//! cannot grant host authority. Local-only adapters keep bounded volatile state
//! and make no durability claim. Resource validation currently supports pinned,
//! supervisor-authorized `db.NAME` bindings on the standalone Linux VM path.
//! Replication, quorum writes, and automatic failover are unsupported in 0.0.9.
//! Cluster capability queries return false; replication operations return an
//! explicit unsupported outcome without performing a local write. A future
//! storage service will own consensus, not the VM's core scheduling semantics.

module std.vm.DistributedStorage.

/// Adapter represents one VM-owned storage backend instance.
/// Input: validated storage policy.
/// Output: an opaque adapter descriptor.
/// Transformation: owns lifecycle state and backend access through the VM.

pub opaque type Adapter.

/// AtomicAppendProof represents an adapter's atomic append sequence boundary.
/// Input: adapter capability state and current sequence.
/// Output: an opaque proof descriptor for append atomicity.
/// Transformation: lets conformance tests prove failed appends do not advance
/// the durable sequence boundary.

pub opaque type AtomicAppendProof.

/// CompareAndSwapToken represents one observed adapter sequence.
/// Input: adapter sequence observed before an append attempt.
/// Output: an opaque optimistic concurrency token.
/// Transformation: prevents stale writers from overwriting newer checkpoints
/// without exposing adapter internals.

pub opaque type CompareAndSwapToken.

/// DurableFlushProof represents the last successfully flushed sequence.
/// Input: adapter capability state and flush lifecycle.
/// Output: an opaque proof descriptor for durable flush progress.
/// Transformation: lets conformance tests prove failed or timed-out flushes do
/// not advance the durable replay boundary.

pub opaque type DurableFlushProof.

/// Mode represents one distributed storage backend class.
/// Input: mode constructor such as local-only, durable, or cluster.
/// Output: an opaque storage mode descriptor.
/// Transformation: keeps backend capability checks inside the VM storage lane.

pub opaque type Mode.

/// Outcome represents one storage lifecycle result.
/// Input: storage adapter operation.
/// Output: opened, appended, flushed, compacted, loaded, missing, closed,
/// unavailable, stale, checksum-mismatch, finalize-failed, flush-timed-out,
/// partial-write, or unsupported-operation descriptor.
/// Transformation: makes storage success and failure paths typed at the Terlan
/// boundary.

pub opaque type Outcome.

/// Policy represents one storage adapter policy.
/// Input: adapter name, mode, and availability.
/// Output: an opaque storage policy descriptor.
/// Transformation: validates selected backend behavior without exposing backend
/// internals to Terlan source.

pub opaque type Policy.

/// ResourceHandleValidationProof represents the last validated handle set.
/// Input: adapter capability state and resource handle validation lifecycle.
/// Output: an opaque proof descriptor for validated handle count and storage
/// sequence.
/// Transformation: lets conformance tests prove missing resource handles do not
/// advance validation proof metadata.

pub opaque type ResourceHandleValidationProof.

/// SchemaMigrationProof represents the current adapter schema version.
/// Input: adapter capability state and schema migration lifecycle.
/// Output: an opaque proof descriptor for schema version and storage sequence.
/// Transformation: lets conformance tests prove stale schema migrations do not
/// mutate adapter schema state or advance schema proof metadata.

pub opaque type SchemaMigrationProof.

/// Snapshot represents one deterministic storage checkpoint descriptor.
/// Input: checkpoint id, sequence, and distributed state snapshot.
/// Output: an opaque storage snapshot descriptor.
/// Transformation: binds state snapshots to storage ordering and checksum
/// validation.

pub opaque type Snapshot.

/// SnapshotIsolationProof represents one validated isolated checkpoint view.
/// Input: loaded checkpoint id, sequence, and checksum.
/// Output: an opaque proof descriptor for snapshot isolation.
/// Transformation: lets conformance tests prove later adapter mutations do not
/// rewrite an already issued checkpoint view.

pub opaque type SnapshotIsolationProof.

/// TransactionalBatchProof represents the last all-or-nothing batch commit.
/// Input: adapter capability state and batch append lifecycle.
/// Output: an opaque proof descriptor for the last committed batch.
/// Transformation: lets conformance tests prove partial batch attempts do not
/// mutate adapter state or advance batch commit metadata.

pub opaque type TransactionalBatchProof.

/// Returns the actual schema version for schema migration outcomes.
/// Input: outcome descriptor.
/// Output: actual schema version, or zero when the outcome does not carry
/// schema metadata.
/// Transformation: exposes schema migration diagnostics without exposing
/// adapter internals.

pub actual_schema(outcome: Outcome): Int.

/// Returns the actual sequence for compare-and-swap token mismatch outcomes.
/// Input: outcome descriptor.
/// Output: current adapter sequence number, or zero when the outcome is not a
/// compare-and-swap token mismatch.
/// Transformation: exposes stale writer diagnostics without exposing adapter
/// internals.

pub actual_sequence(outcome: Outcome): Int.

/// Creates a storage adapter from a policy.
/// Input: storage policy.
/// Output: closed adapter descriptor.
/// Transformation: binds lifecycle operations to one VM-owned backend policy.

pub adapter(policy: Policy): Adapter.

/// Appends a storage snapshot.
/// Input: adapter receiver and snapshot descriptor.
/// Output: appended, partial-write, stale, unavailable, or unsupported outcome
/// descriptor.
/// Transformation: delegates write ordering and stale replay rejection to the VM
/// storage lane.

pub (adapter: Adapter) append(snapshot: Snapshot): Outcome.

/// Returns the current atomic append proof.
/// Input: adapter receiver.
/// Output: atomic append proof descriptor.
/// Transformation: captures the sequence boundary that failed append attempts
/// must not advance.

pub (adapter: Adapter) atomic_append_proof(): AtomicAppendProof.

/// Returns the number of snapshots covered by a transactional batch proof.
/// Input: transactional batch proof descriptor.
/// Output: committed snapshot count for the last batch.
/// Transformation: exposes all-or-nothing batch conformance without exposing
/// adapter internals.

pub batch_committed_count(proof: TransactionalBatchProof): Int.

/// Returns the first sequence covered by a transactional batch proof.
/// Input: transactional batch proof descriptor.
/// Output: first sequence committed by the last batch.
/// Transformation: exposes all-or-nothing batch conformance without exposing
/// adapter internals.

pub batch_first_sequence(proof: TransactionalBatchProof): Int.

/// Returns the last sequence covered by a transactional batch proof.
/// Input: transactional batch proof descriptor.
/// Output: last sequence committed by the last batch.
/// Transformation: exposes all-or-nothing batch conformance without exposing
/// adapter internals.

pub batch_last_sequence(proof: TransactionalBatchProof): Int.

/// Returns whether an adapter can perform cluster replication.
/// Input: adapter receiver.
/// Output: `false` in 0.0.9, including for configured durable adapters.
/// Transformation: exposes deterministic capability checks before
/// `require_cluster_replication`.

pub (adapter: Adapter) can_cluster_replicate(): Bool.

/// Builds a checkpoint descriptor from distributed state.
/// Input: checkpoint id, non-zero sequence, and distributed state snapshot.
/// Output: storage snapshot descriptor.
/// Transformation: attaches deterministic storage metadata to a VM state
/// checkpoint.

pub checkpoint(checkpoint_id: String, sequence: Int, state: std.vm.DistributedState.Snapshot): Snapshot.

/// Returns the checkpoint id associated with a lifecycle outcome.
/// Input: outcome descriptor.
/// Output: checkpoint id text, or an empty string when the outcome has no
/// checkpoint id.
/// Transformation: exposes stable checkpoint metadata for diagnostics and
/// recovery without exposing snapshot internals.

pub checkpoint_id(outcome: Outcome): String.

/// Returns the application schema tag of a created or loaded checkpoint.
/// Input: a checkpoint owned by the calling actor.
/// Output: its positive application schema version.
/// Transformation: lets callers select application-level restore handling
/// without conflating their schema with the VM's versioned logical encoding.

pub checkpoint_schema(snapshot: Snapshot): Int.

/// Builds a logical checkpoint with an explicit application schema version.
/// Input: checkpoint identity, nonzero sequence, positive schema, and state.
/// Output: an immutable actor-owned storage checkpoint.
/// Transformation: tags the existing logical encoding without transforming
/// application data. The application owns schema meaning and migration; append
/// rejects tags that differ from the durable backend's current schema.

pub checkpoint_with_schema(checkpoint_id: String, sequence: Int, schema: Int, state: std.vm.DistributedState.Snapshot): Snapshot.

/// Returns the checksum associated with a lifecycle outcome.
/// Input: outcome descriptor.
/// Output: checksum integer or zero when the outcome has no checksum.
/// Transformation: exposes checksum metadata for audit and validation without
/// leaking the snapshot representation.

pub checksum(outcome: Outcome): Int.

/// Closes a storage adapter.
/// Input: adapter receiver.
/// Output: closed, unavailable, or unsupported outcome descriptor.
/// Transformation: makes adapter lifecycle shutdown explicit.

pub (adapter: Adapter) close(): Outcome.

/// Builds the cluster storage mode.
/// Input: no runtime input.
/// Output: cluster storage mode.
/// Transformation: selects replication-aware checkpoint behavior when a backend
/// supports it.

pub cluster(): Mode.

/// Compacts old storage snapshots.
/// Input: adapter receiver and first sequence to retain.
/// Output: compacted, unavailable, or unsupported outcome descriptor.
/// Transformation: delegates deterministic retention to the VM storage lane.

pub (adapter: Adapter) compact(retain_from_sequence: Int): Outcome.

/// Appends a storage snapshot if the compare-and-swap token is current.
/// Input: adapter receiver, snapshot descriptor, and compare-and-swap token.
/// Output: appended, stale-token, partial-write, stale, unavailable, or
/// unsupported outcome descriptor.
/// Transformation: makes optimistic concurrency explicit at the storage adapter
/// boundary.

pub (adapter: Adapter) compare_and_swap_append(snapshot: Snapshot, token: CompareAndSwapToken): Outcome.

/// Returns a compare-and-swap append token for the current sequence.
/// Input: adapter receiver.
/// Output: compare-and-swap token descriptor.
/// Transformation: captures the adapter sequence that must still be current
/// before a guarded append can commit.

pub (adapter: Adapter) compare_and_swap_token(): CompareAndSwapToken.

/// Builds the durable storage mode.
/// Input: no runtime input.
/// Output: durable storage mode.
/// Transformation: selects persistence-backed behavior when an adapter is
/// available.

pub durable(): Mode.

/// Returns the current durable flush proof.
/// Input: adapter receiver.
/// Output: durable flush proof descriptor.
/// Transformation: captures the flushed sequence boundary that failed or timed
/// out flush attempts must not advance. Local-only adapters fail explicitly
/// rather than issuing a persistence proof for volatile memory.

pub (adapter: Adapter) durable_flush_proof(): DurableFlushProof.

/// Returns the sequence covered by a durable flush proof.
/// Input: durable flush proof descriptor.
/// Output: last successfully flushed sequence.
/// Transformation: exposes fsync/equivalent conformance without exposing
/// adapter internals.

pub durable_flush_sequence(proof: DurableFlushProof): Int.

/// Returns the expected checksum for checksum-mismatch outcomes.
/// Input: outcome descriptor.
/// Output: expected checksum integer, or zero when the outcome is not a checksum
/// mismatch.
/// Transformation: exposes checksum mismatch diagnostics without exposing the
/// snapshot representation.

pub expected_checksum(outcome: Outcome): Int.

/// Returns the expected entry count for partial-write outcomes.
/// Input: outcome descriptor.
/// Output: expected entry count, or zero when the outcome is not partial-write.
/// Transformation: exposes bounded recovery metadata without exposing the
/// adapter log representation. Atomic local/SQLite outcomes are not partial
/// writes and return zero. An indeterminate commit is not a measured partial
/// write; zero does not establish that an unacknowledged write rolled back.

pub expected_entries(outcome: Outcome): Int.

/// Returns the expected schema version for schema migration failures.
/// Input: outcome descriptor.
/// Output: expected schema version, or zero when the outcome is not a stale
/// schema migration failure.
/// Transformation: exposes schema migration diagnostics without exposing
/// adapter internals.

pub expected_schema(outcome: Outcome): Int.

/// Returns the expected sequence for compare-and-swap token mismatch outcomes.
/// Input: outcome descriptor.
/// Output: expected sequence number, or zero when the outcome is not a
/// compare-and-swap token mismatch.
/// Transformation: exposes stale writer diagnostics without exposing adapter
/// internals.

pub expected_sequence(outcome: Outcome): Int.

/// Flushes pending storage writes.
/// Input: adapter receiver.
/// Output: flushed, finalize-failed, flush-timed-out, unavailable, or
/// unsupported outcome descriptor.
/// Transformation: durable adapters acknowledge the real storage flush;
/// local-only adapters establish an in-memory ordering barrier only.

pub (adapter: Adapter) flush(): Outcome.

/// Builds the default force-local storage policy.
/// Input: no runtime input.
/// Output: local-only available policy.
/// Transformation: creates bounded actor-owned volatile storage without a
/// filesystem binding. Separate adapters do not share state. Actor exit or VM
/// shutdown loses its data; this policy does not support durable-flush proofs.

pub force_local(): Policy.

/// Returns the incoming sequence for stale-snapshot outcomes.
/// Input: outcome descriptor.
/// Output: incoming sequence number, or zero when the outcome is not stale.
/// Transformation: exposes rejected checkpoint ordering as typed metadata.

pub incoming_sequence(outcome: Outcome): Int.

/// Returns whether an outcome represents a failed storage operation.
/// Input: outcome descriptor.
/// Output: `true` for unavailable, unsupported, stale, checksum mismatch,
/// finalize-failed, partial-write, and missing snapshot outcomes.
/// Transformation: exposes success/failure branching as typed metadata instead
/// of requiring string comparisons.

pub is_failure(outcome: Outcome): Bool.

/// Returns whether an outcome represents a successful storage operation.
/// Input: outcome descriptor.
/// Output: `true` for opened, appended, flushed, compacted, loaded, and closed
/// outcomes.
/// Transformation: exposes success branching as typed metadata instead of
/// requiring callers to negate failure state.

pub is_success(outcome: Outcome): Bool.

/// Returns the checkpoint id covered by a snapshot isolation proof.
/// Input: snapshot isolation proof descriptor.
/// Output: isolated checkpoint id.
/// Transformation: exposes stable snapshot identity without exposing adapter
/// internals.

pub isolation_checkpoint_id(proof: SnapshotIsolationProof): String.

/// Returns the checksum covered by a snapshot isolation proof.
/// Input: snapshot isolation proof descriptor.
/// Output: isolated checkpoint checksum.
/// Transformation: exposes stable snapshot integrity evidence without exposing
/// adapter internals.

pub isolation_checksum(proof: SnapshotIsolationProof): Int.

/// Returns the sequence covered by a snapshot isolation proof.
/// Input: snapshot isolation proof descriptor.
/// Output: isolated checkpoint sequence.
/// Transformation: exposes stable snapshot ordering without exposing adapter
/// internals.

pub isolation_sequence(proof: SnapshotIsolationProof): Int.

/// Returns the textual lifecycle outcome kind.
/// Input: outcome descriptor.
/// Output: stable outcome kind text.
/// Transformation: exposes storage result classification for tests, logs, and
/// tools.

pub kind(outcome: Outcome): String.

/// Loads a checkpoint by id.
/// Input: adapter receiver and checkpoint id.
/// Output: loaded, missing, unavailable, checksum-mismatch, or unsupported
/// outcome descriptor.
/// Transformation: validates checksum and backend capability before exposing the
/// loaded descriptor.

pub (adapter: Adapter) load_snapshot(checkpoint_id: String): Outcome.

/// Extracts a loaded snapshot from a lifecycle outcome.
/// Input: loaded outcome descriptor.
/// Output: storage snapshot descriptor.
/// Transformation: keeps snapshot extraction typed and avoids diagnostic
/// parsing.

pub loaded_snapshot(outcome: Outcome): Snapshot.

/// Builds the local-only storage mode.
/// Input: no runtime input.
/// Output: local-only storage mode.
/// Transformation: selects force-local VM behavior for tests and development.

pub local_only(): Mode.

/// Returns the local sequence for stale-snapshot outcomes.
/// Input: outcome descriptor.
/// Output: local sequence number, or zero when the outcome is not stale.
/// Transformation: exposes stale replay diagnostics without exposing adapter
/// state.

pub local_sequence(outcome: Outcome): Int.

/// Migrates the adapter schema when the expected version is current.
/// Input: adapter receiver, expected current schema version, and next schema
/// version.
/// Output: schema-migrated or schema-migration-mismatch outcome descriptor.
/// Transformation: makes schema evolution explicit at the storage adapter
/// boundary instead of allowing hidden adapter-specific rewrites.

pub (adapter: Adapter) migrate_schema(expected_schema: Int, next_schema: Int): Outcome.

/// Returns the missing resource handle for validation failures.
/// Input: resource-handle-validation-failed outcome descriptor.
/// Output: missing durable resource handle id, or empty text for other outcomes.
/// Transformation: exposes resource recovery diagnostics without exposing
/// adapter internals.

pub missing_resource_handle(outcome: Outcome): String.

/// Returns the storage mode kind associated with an outcome.
/// Input: outcome descriptor.
/// Output: stable mode kind text, or an empty string when the outcome does not
/// carry backend mode metadata.
/// Transformation: exposes backend class metadata for capability decisions
/// without exposing adapter state.

pub mode_kind(outcome: Outcome): String.

/// Opens a storage adapter.
/// Input: adapter receiver.
/// Output: lifecycle outcome descriptor.
/// Transformation: performs deterministic capability and availability checks.

pub (adapter: Adapter) open(): Outcome.

/// Returns the lifecycle operation kind associated with an outcome.
/// Input: outcome descriptor.
/// Output: stable operation kind text, or an empty string when the outcome does
/// not carry operation metadata.
/// Transformation: exposes capability/failure operation metadata without
/// exposing backend internals or debug text.

pub operation_kind(outcome: Outcome): String.

/// Returns the persisted entry count for partial-write outcomes.
/// Input: outcome descriptor.
/// Output: persisted entry count, or zero when the outcome is not partial-write.
/// Transformation: exposes partial persistence progress as typed metadata for
/// recovery and diagnostics. Atomic local/SQLite outcomes return zero rather
/// than guessing partial progress. For indeterminate commits, reconcile stored
/// checkpoint identities; this getter is not evidence of rollback.

pub persisted_entries(outcome: Outcome): Int.

/// Builds a storage policy descriptor.
/// Input: policy name, backend mode, and a requested availability flag.
/// Output: storage policy descriptor.
/// Transformation: durable availability additionally requires a matching
/// supervisor-provided binding; source code cannot grant filesystem authority.

pub policy(name: String, mode: Mode, available: Bool): Policy.

/// Returns whether the selected backend is available.
/// Input: storage policy descriptor.
/// Output: `true` when the policy points at an available backend.
/// Transformation: exposes deterministic backend availability for validation
/// without opening the adapter.

pub policy_available(policy: Policy): Bool.

/// Returns whether an adapter's selected backend is available.
/// Input: adapter receiver.
/// Output: `true` when the selected backend is available.
/// Transformation: exposes deterministic backend availability without probing
/// backend internals.

pub (adapter: Adapter) policy_available(): Bool.

/// Returns whether a policy can perform cluster replication.
/// Input: storage policy descriptor.
/// Output: `false` in 0.0.9; no replication provider is supported.
/// Transformation: exposes deterministic capability checks before adapter
/// lifecycle calls.

pub policy_can_cluster_replicate(policy: Policy): Bool.

/// Returns the stable policy mode kind.
/// Input: storage policy descriptor.
/// Output: mode kind text.
/// Transformation: exposes adapter mode selection without leaking backend
/// internals.

pub policy_mode_kind(policy: Policy): String.

/// Returns the policy mode kind attached to an adapter.
/// Input: adapter receiver.
/// Output: mode kind text.
/// Transformation: exposes adapter mode selection without exposing adapter
/// state or backend internals.

pub (adapter: Adapter) policy_mode_kind(): String.

/// Returns the stable policy name.
/// Input: storage policy descriptor.
/// Output: policy name text.
/// Transformation: exposes adapter selection identity without leaking backend
/// internals.

pub policy_name(policy: Policy): String.

/// Returns the policy name attached to an adapter.
/// Input: adapter receiver.
/// Output: policy name text.
/// Transformation: exposes adapter selection identity without exposing adapter
/// state or backend internals.

pub (adapter: Adapter) policy_name(): String.

/// Returns the sequence boundary covered by an atomic append proof.
/// Input: atomic append proof descriptor.
/// Output: observed adapter sequence.
/// Transformation: exposes atomic append conformance without exposing adapter
/// internals.

pub proof_sequence(proof: AtomicAppendProof): Int.

/// Returns the stable failure reason associated with an outcome.
/// Input: outcome descriptor.
/// Output: stable reason code for failure outcomes, or an empty string for
/// successful outcomes.
/// Transformation: exposes machine-readable storage diagnostics without
/// leaking backend-specific error messages.

pub reason(outcome: Outcome): String.

/// Returns the recovery action associated with a failure outcome.
/// Input: outcome descriptor.
/// Output: stable recovery action code, or an empty string when no recovery
/// action is required.
/// Transformation: exposes recovery routing as typed storage metadata instead
/// of coupling migration or fault code to diagnostic strings.

pub recovery_action(outcome: Outcome): String.

/// Registers a supervisor-authorized resource name with the adapter.
/// Input: adapter receiver and durable resource handle id.
/// Output: resource-handles-validated or resource-handle-validation-failed
/// outcome descriptor.
/// Transformation: db.NAME resolves only to the supervisor's identity-pinned
/// storage binding NAME. The VM asynchronously checks the real worker identity
/// before registering it. Unknown names cannot create authority. Registrations
/// are actor-local and must be re-established and checked after restart; strings
/// restored from a checkpoint never restore authority. Other providers are not
/// currently supported. Volatile adapters do not gain storage durability.

pub (adapter: Adapter) register_resource_handle(handle: String): Outcome.

/// Requests storage snapshot replication, unsupported in 0.0.9.
/// Input: adapter receiver and snapshot descriptor.
/// Output: an unsupported outcome descriptor, never a successful write receipt.
/// Transformation: validates actor-owned arguments and rejects replication
/// without mutating storage. No local append or alternative provider is silently
/// substituted. Rejection coverage is not replication capability coverage.

pub (adapter: Adapter) replicate_snapshot(snapshot: Snapshot): Outcome.

/// Requires atomic append support.
/// Input: adapter receiver.
/// Output: opened or unavailable outcome descriptor.
/// Transformation: exposes deterministic append capability checks before
/// writing checkpoints.

pub (adapter: Adapter) require_atomic_append(): Outcome.

/// Checks for cluster replication support, unsupported in 0.0.9.
/// Input: adapter receiver.
/// Output: an unsupported outcome descriptor.
/// Transformation: rejects the unsupported capability regardless of a caller's
/// availability flag or whether a local durable backend has been configured.

pub (adapter: Adapter) require_cluster_replication(): Outcome.

/// Requires durable flush proof support.
/// Input: adapter receiver.
/// Output: opened, unavailable, or unsupported outcome descriptor.
/// Transformation: local-only adapters report unsupported. Durable adapters
/// expose fsync/equivalent durability
/// capability checks before accepting a durable boundary proof.

pub (adapter: Adapter) require_durable_flush(): Outcome.

/// Requires resource handle validation support.
/// Input: adapter receiver.
/// Output: opened or unavailable outcome descriptor.
/// Transformation: requires an open adapter and supervisor-configured, identity-
/// pinned database resources. Unconfigured providers return unsupported; this
/// capability check does not itself validate a resource or confer authority.

pub (adapter: Adapter) require_resource_handle_validation(): Outcome.

/// Requires schema migration support.
/// Input: adapter receiver.
/// Output: opened or unavailable outcome descriptor.
/// Transformation: exposes deterministic schema migration capability checks
/// before accepting adapter schema changes.

pub (adapter: Adapter) require_schema_migration(): Outcome.

/// Requires snapshot isolation support.
/// Input: adapter receiver.
/// Output: opened or unavailable outcome descriptor.
/// Transformation: exposes deterministic snapshot isolation capability checks
/// before loading checkpoint views.

pub (adapter: Adapter) require_snapshot_isolation(): Outcome.

/// Requires transactional batch append support.
/// Input: adapter receiver.
/// Output: opened or unavailable outcome descriptor.
/// Transformation: exposes deterministic all-or-nothing batch capability checks
/// before accepting grouped checkpoint writes.

pub (adapter: Adapter) require_transactional_batch(): Outcome.

/// Returns whether a failure outcome requires storage recovery work.
/// Input: outcome descriptor.
/// Output: `true` for stale snapshot, checksum mismatch, finalize failure, and
/// partial-write outcomes.
/// Transformation: separates recovery-required failures from ordinary
/// capability or lookup outcomes without string comparisons.

pub requires_recovery(outcome: Outcome): Bool.

/// Returns the count covered by a resource handle validation proof.
/// Input: resource handle validation proof descriptor.
/// Output: count of handles covered by the last successful validation.
/// Transformation: exposes resource validation conformance without exposing
/// adapter internals.

pub resource_handle_count(proof: ResourceHandleValidationProof): Int.

/// Returns the storage sequence covered by a resource validation proof.
/// Input: resource handle validation proof descriptor.
/// Output: adapter storage sequence when resource handles were validated.
/// Transformation: binds resource validation to replay ordering without
/// exposing adapter internals.

pub resource_handle_sequence(proof: ResourceHandleValidationProof): Int.

/// Returns the current resource handle validation proof.
/// Input: adapter receiver.
/// Output: resource handle validation proof descriptor.
/// Transformation: captures the last validated handle count and storage
/// sequence that missing-handle failures must not advance.
/// Proofs are immutable historical observations, not leases or future liveness
/// guarantees. Unsupported or closed adapters cannot issue these proofs.

pub (adapter: Adapter) resource_handle_validation_proof(): ResourceHandleValidationProof.

/// Restores checkpoint contents as a new actor-owned mutable state store.
/// Input: an immutable logical checkpoint belonging to the calling actor.
/// Output: a new state store with the original scopes, versions, policies, and values.
/// Transformation: decodes the versioned, bounded representation and validates
/// the current image's atom vocabulary. This does not open a durable backend.

pub (snapshot: Snapshot) restore(): std.vm.DistributedState.Store.

/// Returns the retained snapshot count for compaction outcomes.
/// Input: outcome descriptor.
/// Output: retained snapshot count, or zero when the outcome is not compacted.
/// Transformation: exposes deterministic compaction progress without exposing
/// adapter log internals.

pub retained_snapshots(outcome: Outcome): Int.

/// Returns the current schema migration proof.
/// Input: adapter receiver.
/// Output: schema migration proof descriptor.
/// Transformation: captures the schema version and storage sequence that stale
/// migration attempts must not advance.

pub (adapter: Adapter) schema_migration_proof(): SchemaMigrationProof.

/// Returns the storage sequence covered by a schema migration proof.
/// Input: schema migration proof descriptor.
/// Output: adapter storage sequence when the schema proof was issued.
/// Transformation: binds schema evolution to replay ordering without exposing
/// adapter internals.

pub schema_sequence(proof: SchemaMigrationProof): Int.

/// Returns the schema version covered by a schema migration proof.
/// Input: schema migration proof descriptor.
/// Output: current adapter schema version.
/// Transformation: exposes schema evolution conformance without exposing
/// adapter internals.

pub schema_version(proof: SchemaMigrationProof): Int.

/// Returns the sequence associated with a lifecycle outcome.
/// Input: outcome descriptor.
/// Output: storage sequence number or zero when the outcome has no sequence.
/// Transformation: exposes deterministic checkpoint ordering for diagnostics
/// without exposing backend internals.

pub sequence(outcome: Outcome): Int.

/// Returns a snapshot isolation proof for a checkpoint.
/// Input: adapter receiver and checkpoint id.
/// Output: snapshot isolation proof descriptor.
/// Transformation: validates and freezes one checkpoint view before later
/// adapter writes or compaction can occur.

pub (adapter: Adapter) snapshot_isolation_proof(checkpoint_id: String): SnapshotIsolationProof.

/// Appends a group of snapshots as one all-or-nothing transaction.
/// Input: adapter receiver and ordered snapshot descriptors.
/// Output: batch-appended, partial-write, stale, checksum-mismatch,
/// unavailable, or unsupported outcome descriptor.
/// Transformation: validates every checkpoint before mutating adapter state so
/// a partial batch cannot become actor-visible.

pub (adapter: Adapter) transactional_batch_append(snapshots: List[Snapshot]): Outcome.

/// Returns the current transactional batch proof.
/// Input: adapter receiver.
/// Output: transactional batch proof descriptor.
/// Transformation: captures the last committed batch boundary that failed
/// partial batch attempts must not advance.

pub (adapter: Adapter) transactional_batch_proof(): TransactionalBatchProof.

/// Revalidates registered resource names against their authorized live workers.
/// Input: adapter receiver and durable resource handle ids.
/// Output: resource-handles-validated or resource-handle-validation-failed
/// outcome descriptor.
/// Transformation: checks every resource identity again without blocking the
/// actor owner. At most 16 unique names are accepted; duplicate or oversized
/// lists are invalid. Empty validation succeeds with count zero. Failed checks
/// do not advance the previous proof. Observations are sequential, not an atomic
/// snapshot across resources, and all probes share one bounded deadline.

pub (adapter: Adapter) validate_resource_handles(handles: List[String]): Outcome.

/// Returns the count validated by a successful resource handle check.
/// Input: resource-handles-validated outcome descriptor.
/// Output: validated handle count, or zero for other outcomes.
/// Transformation: exposes resource validation metadata for conformance tests
/// and replay diagnostics.

pub validated_resource_count(outcome: Outcome): Int.

//! Terlan VM distributed fault and recovery contract.
//! `std.vm.Fault` exposes typed descriptors for scheduler-owned fault
//! classification, recovery windows, and migration rollback diagnostics. The VM
//! owns event ordering, duplicate replay, and state-transition validation.
//! Monitors are mutable actor-owned resources driven by caller-supplied ticks
//! and observations. They do not discover peers, probe networks, replicate data,
//! or migrate live actors. Rollbacks are diagnostic descriptors; compatibility
//! classifies the supplied policy flags, not the capabilities of a remote node.

module std.vm.Fault.

/// Failure represents one replayable distributed failure envelope.
/// Input: heartbeat, partition, recovery, or migration failure data.
/// Output: an opaque failure descriptor.
/// Transformation: gives source and tooling a stable diagnostic shape while the
/// VM owns failure ordering.

pub opaque type Failure.

/// Monitor is a VM-owned distributed fault state machine.
/// Input: active node identities and one validated fault policy.
/// Output: a resource handle for heartbeat, partition, and recovery events.
/// Transformation: delegates every transition, replay check, and diagnostic to
/// the canonical distributed scheduler.

pub opaque type Monitor.

/// Policy represents distributed fault detection thresholds.
/// Input: heartbeat suspicion, isolation, and recovery-window ticks.
/// Output: an opaque fault policy descriptor.
/// Transformation: keeps threshold ordering and safe-default validation inside
/// the VM scheduler.

pub opaque type Policy.

/// Recovery represents one bounded recovery attempt.
/// Input: node id and recovery tick.
/// Output: an opaque recovery descriptor.
/// Transformation: keeps recovery-window expiry and completion sequencing under
/// VM ownership.

pub opaque type Recovery.

/// Rollback represents one migration rollback descriptor.
/// Input: actor id, migration sequence, phase, tick, and reason.
/// Output: an opaque rollback descriptor.
/// Transformation: records idempotent migration rollback metadata without
/// exposing in-flight scheduler tables.

pub opaque type Rollback.

/// State represents one node fault state observation.
/// Input: node id and state tag.
/// Output: an opaque fault state descriptor.
/// Transformation: records `recovered`, `suspected`, `degraded`, `isolated`,
/// and `recovering` observations without leaking scheduler internals.

pub opaque type State.

/// Transition represents one deterministic fault-state transition.
/// Input: node, tick, target state, and reason.
/// Output: an opaque transition descriptor.
/// Transformation: lets the VM validate monotonic ticks, legal transitions, and
/// duplicate replay.

pub opaque type Transition.

/// Begins a bounded recovery attempt for one isolated node.

pub (monitor: Monitor) begin_recovery(node_id: String, tick: Int, reason: String): Transition.

/// Classifies a missed heartbeat.
/// Input: policy descriptor, node id, tick, heartbeat gap, and reason.
/// Output: transition descriptor.
/// Transformation: asks the VM scheduler to produce a deterministic suspected
/// transition when the policy threshold is exceeded.

pub classify_heartbeat(policy: Policy, node_id: String, tick: Int, heartbeat_gap_ticks: Int, reason: String): Transition.

/// Releases the monitor resource; subsequent operations fail deterministically.

pub (monitor: Monitor) close(): Unit.

/// Classifies distributed compatibility as `supported`,
/// `fallback_local_only`, or `feature_unsupported`.

pub compatibility(partition_tolerant: Bool, local_fallback_available: Bool): String.

/// Completes recovery and refreshes the node heartbeat.

pub (monitor: Monitor) complete(node_id: String, tick: Int, reason: String): Transition.

/// Completes one recovery attempt.
/// Input: recovery descriptor, completion tick, and reason.
/// Output: transition descriptor.
/// Transformation: delegates recovery completion and heartbeat refresh to the
/// VM scheduler.

pub complete_recovery(recovery: Recovery, tick: Int, reason: String): Transition.

/// Marks a suspected node degraded before isolation.

pub (monitor: Monitor) degrade(node_id: String, tick: Int, reason: String): Transition.

/// Re-isolates a recovering node after its policy window expires.

pub (monitor: Monitor) expire(node_id: String, tick: Int, reason: String): Option[Transition].

/// Expires one recovery attempt.
/// Input: policy descriptor, recovery descriptor, expiry tick, and reason.
/// Output: failure descriptor.
/// Transformation: records deterministic recovery-window expiry diagnostics.

pub expire_recovery(policy: Policy, recovery: Recovery, tick: Int, reason: String): Failure.

/// Converts a rollback descriptor to a failure envelope descriptor.
/// Input: rollback descriptor.
/// Output: failure descriptor.
/// Transformation: exposes migration rollback as the same typed diagnostic
/// stream used by heartbeat, partition, and recovery failures.

pub failure(rollback: Rollback): Failure.

/// Returns the stable operational diagnostic represented by a failure.

pub failure_diagnostic_kind(failure: Failure): String.

/// Returns the stable machine-readable failure kind.

pub failure_kind(failure: Failure): String.

/// Returns the node associated with a failure.

pub failure_node_id(failure: Failure): String.

/// Returns the stable reason associated with a failure.

pub failure_reason(failure: Failure): String.

/// Returns the scheduler tick associated with a failure.

pub failure_tick(failure: Failure): Int.

/// Replays ordered failure envelopes after an exclusive tick cursor.

pub (monitor: Monitor) failures_after(tick: Int): List[Failure].

/// Applies the isolation threshold and returns the resulting transition.

pub (monitor: Monitor) isolate(node_id: String, tick: Int, reason: String): Option[Transition].

/// Classifies partition isolation after suspicion.
/// Input: policy descriptor, node id, tick, heartbeat gap, and reason.
/// Output: transition descriptor.
/// Transformation: asks the VM scheduler to validate isolation threshold and
/// legal state progression.

pub isolate_partition(policy: Policy, node_id: String, tick: Int, heartbeat_gap_ticks: Int, reason: String): Transition.

/// Builds a migration partial-commit rollback descriptor.
/// Input: actor id, migration sequence, source node, target node, phase, tick,
/// and reason.
/// Output: rollback descriptor.
/// Transformation: records idempotent partial-commit rollback metadata for the
/// VM migration safety lane.

pub migration_partial_commit(actor_id: String, sequence: Int, from_node_id: String, to_node_id: String, phase: String, tick: Int, reason: String): Rollback.

/// Builds a migration-timeout rollback descriptor.
/// Input: actor id, migration sequence, source node, target node, phase, tick,
/// and reason.
/// Output: rollback descriptor.
/// Transformation: records idempotent timeout rollback metadata for the VM
/// migration safety lane.

pub migration_timeout(actor_id: String, sequence: Int, from_node_id: String, to_node_id: String, phase: String, tick: Int, reason: String): Rollback.

/// Creates a VM-owned fault monitor for a non-empty set of unique nodes.

pub monitor(node_ids: List[String], policy: Policy): Monitor.

/// Builds a fault policy descriptor.
/// Input: suspicion threshold, isolation threshold, and recovery-window ticks.
/// Output: policy descriptor.
/// Transformation: delegates threshold validation to the VM fault scheduler.

pub policy(suspicion_threshold_ticks: Int, isolation_threshold_ticks: Int, recovery_window_ticks: Int): Policy.

/// Records a heartbeat and reports `recorded` or `duplicate_suppressed`.

pub (monitor: Monitor) record_heartbeat(node_id: String, tick: Int): String.

/// Resolves mismatched peer policies to the stricter threshold in each field.

pub resolve_policy(local: Policy, peer: Policy): Policy.

/// Builds a typed failure for a rejected stale placement update.

pub stale_placement_update(actor_id: String, node_id: String, incoming_sequence: Int, current_sequence: Int, tick: Int, reason: String): Failure.

/// Starts recovery for one isolated node.
/// Input: node id, tick, and reason.
/// Output: recovery descriptor.
/// Transformation: records a bounded recovery attempt for later completion or
/// expiry.

pub start_recovery(node_id: String, tick: Int, reason: String): Recovery.

/// Builds a fault state descriptor.
/// Input: node id and state tag.
/// Output: state descriptor.
/// Transformation: normalizes source-visible fault states for diagnostics and
/// test scenarios.

pub state(node_id: String, state: String): State.

/// Returns the canonical state name for one monitored node.

pub (monitor: Monitor) state_name(node_id: String): String.

/// Applies the suspicion threshold and returns the resulting transition.

pub (monitor: Monitor) suspect(node_id: String, tick: Int, reason: String): Option[Transition].

/// Returns the stable operational diagnostic represented by a transition.

pub transition_diagnostic_kind(transition: Transition): String.

/// Returns the state after a transition.

pub transition_next_state(transition: Transition): String.

/// Returns the node id recorded by a transition.

pub transition_node_id(transition: Transition): String.

/// Returns the state before a transition.

pub transition_previous_state(transition: Transition): String.

/// Returns the stable reason recorded by a transition.

pub transition_reason(transition: Transition): String.

/// Returns the scheduler tick recorded by a transition.

pub transition_tick(transition: Transition): Int.

/// Replays ordered transitions after an exclusive tick cursor.

pub (monitor: Monitor) transitions_after(tick: Int): List[Transition].

//! Typed request servers implemented in Terlan over VM process primitives.

module std.vm.GenServer.

/// State and reply returned by a synchronous request handler.

pub type CallReply[State, Value] =
    {Atom["gen_server_call_reply"], state: State, reply: Value}.

pub type GenServerCall =
    Atom["gen_server_call"].

pub type GenServerCallReplyTag =
    Atom["gen_server_call_reply"].

pub type GenServerCast =
    Atom["gen_server_cast"].

/// Calls, casts, and stop requests share one concrete value family so a server
/// has exactly one stable AOT mailbox layout.

pub type GenServerCommand[Value] =
    {Atom["gen_server_command"], kind: GenServerCommandKind, request_id: Int, reply_to: std.vm.Process[GenServerReply[Value]], value: Value}.

pub type GenServerCommandKind =
    GenServerCall
  | GenServerCast
  | GenServerStop.

pub type GenServerCommandTag =
    Atom["gen_server_command"].

/// One correlated reply sent from the server to a caller.

pub type GenServerReply[Value] =
    {Atom["gen_server_reply"], request_id: Int, value: Value}.

pub type GenServerReplyTag =
    Atom["gen_server_reply"].

pub type GenServerStop =
    Atom["gen_server_stop"].

pub type GenServerTag =
    Atom["gen_server"].

/// Typed process handle plus a concrete AOT mailbox witness.

pub type ServerRef[Value] =
    {Atom["gen_server"], process: std.vm.Process[GenServerCommand[Value]], witness: Value}.

pub await_reply[Value](request_id: Int, witness: Value): Value.

/// Performs a correlated synchronous request and discards stale replies.

pub call[Value](server: ServerRef[Value], request_id: Int, request: Value): Value.

/// Thin policy wrapper for VM-owned cancellation.

pub cancel[Value](server: ServerRef[Value]): Unit.

/// Queues an asynchronous state-changing event.

pub cast[Value](server: ServerRef[Value], event: Value): Unit.

/// Converts a callback's initialization outcome into explicit service policy.

@pure
pub init_succeeded(init_ok: Bool): Bool.

pub make_ref[Value](process: std.vm.Process[GenServerCommand[Value]], witness: Value): ServerRef[Value].

/// Establishes a VM-owned failure monitor; DOWN delivery remains VM policy.

pub monitor[Value](server: ServerRef[Value]): Unit.

/// Thin policy wrapper for VM-owned symmetric links.

pub relate_peer[Value](server: ServerRef[Value]): Unit.

pub send_reply[Value](reply_to: std.vm.Process[GenServerReply[Value]], request_id: Int, reply: Value): Unit.

/// Runs a replacement-policy server loop.
/// Calls reply with the prior state and install their request as the next
/// state; casts install their value without replying; stop replies with the
/// final state and terminates. More elaborate policies compose this typed loop
/// from ordinary Terlan functions rather than VM framework opcodes.

pub serve[Value](initial: Value): Unit.

pub serve_state[Value](state: Value): Unit.

/// Builds a source-owned service handle after initialization succeeds.
/// The caller creates the statically known entry with `Process.spawn`; this
/// function owns only GenServer policy and never invokes framework magic.

pub start[Value](process: std.vm.Process[GenServerCommand[Value]], witness: Value): ServerRef[Value].

/// Stops the loop and returns the value produced by its terminate callback.

pub stop[Value](server: ServerRef[Value], request_id: Int): Value.

/// Thin policy wrapper for VM-owned deterministic timers.

pub timeout(ticks: Int): Unit.

//! Terlan VM message contract.
//! `std.vm.Message` models typed payloads that can cross runtime process
//! boundaries. It is a target-gated runtime contract and is not part of
//! portable `std.core`.

module std.vm.Message.

/// Message represents one typed runtime process message.
/// Input: type parameter `T`.
/// Output: an opaque message wrapper owned by the selected VM runtime.
/// Transformation: keeps source-level message payloads typed while the VM owns
/// the mailbox envelope and transfer metadata.

pub opaque type Message[T].

/// Reads a typed payload from a VM message.
/// Input: one `Message[T]`.
/// Output: the original payload value.
/// Transformation: projects the payload after VM-owned receive logic has
/// selected and transferred the typed mailbox envelope.

pub unwrap[T](message: Message[T]): T.

/// Wraps a source value as a typed VM message.
/// Input: one payload value.
/// Output: a `Message[T]` carrying that payload.
/// Transformation: marks the payload for typed mailbox delivery without
/// exposing mailbox internals or requiring a source-visible allocation.

pub wrap[T](value: T): Message[T].

/// MessageCodec defines conversion between source values and runtime messages.
/// Input: source payload type `T`.
/// Output: a trait requiring wrapping and unwrapping operations for `Message[T]`.
/// Transformation: gives VM adapters an ordinary trait surface for message
/// encoding without adding send/receive grammar to Terlan source.

pub trait MessageCodec[T] {
    unwrap(message: Message[T]): T.
    wrap(value: T): Message[T].
}.

//! Terlan VM model synchronization contract.
//! `std.vm.ModelSync` exposes source-visible descriptors for typed model keys,
//! optimistic versions, write plans, delete plans, conflict metadata, and
//! adapter capability declarations. The VM owns validation and storage
//! mechanics; Terlan code owns when to build and pass these descriptors.

module std.vm.ModelSync.

/// AdapterContract represents one portable model-sync adapter declaration.
/// Input: adapter name, storage family, and capabilities.
/// Output: an opaque adapter contract descriptor.
/// Transformation: separates portable model-sync capability declaration from
/// backend-specific storage details.

pub opaque type AdapterContract.

/// Capability represents one model-sync adapter capability.
/// Input: capability name such as typed-key, optimistic-version, put, delete,
/// snapshot, or change-stream.
/// Output: an opaque capability descriptor.
/// Transformation: keeps adapter portability checks source-visible.

pub opaque type Capability.

/// Conflict represents one optimistic write conflict.
/// Input: key, current version, and incoming version.
/// Output: an opaque conflict descriptor.
/// Transformation: makes stale-write failures typed and inspectable by source
/// code and tools.

pub opaque type Conflict.

/// Delete represents one optimistic model delete plan.
/// Input: key, expected version, and tombstone version.
/// Output: an opaque delete descriptor.
/// Transformation: exposes delete concurrency metadata without leaking the
/// tombstone representation.

pub opaque type Delete.

/// Key represents one synchronized model row.
/// Input: model name and model id.
/// Output: an opaque model key descriptor.
/// Transformation: validates non-empty model identity through the VM model-sync
/// lane.

pub opaque type Key.

/// PackageStoreAdapter represents a model-sync adapter bound to a Terlan package
/// store.
/// Input: package id and portable adapter contract.
/// Output: an opaque adapter binding descriptor.
/// Transformation: keeps package-backed model sync source-visible without
/// exposing package cache or registry internals.

pub opaque type PackageStoreAdapter.

/// PersistentActorAdapter represents a model-sync adapter bound to a persistent
/// actor.
/// Input: persistent actor id and portable adapter contract.
/// Output: an opaque adapter binding descriptor.
/// Transformation: keeps persistent actor store integration source-visible
/// without exposing actor storage internals.

pub opaque type PersistentActorAdapter.

/// SyncableModel represents a source-visible model declaration.
/// Input: model value type.
/// Output: typed syncable model declaration descriptor.
/// Transformation: lets Terlan code declare a model-sync surface without ORM
/// identity maps, hidden lazy loading, or backend-specific query generation.

pub opaque type SyncableModel[T].

/// Version represents one optimistic write version.
/// Input: monotonic sequence and writer id.
/// Output: an opaque optimistic version descriptor.
/// Transformation: keeps optimistic concurrency metadata typed at the source
/// boundary.

pub opaque type Version.

/// Write represents one optimistic model write plan.
/// Input: key, expected version, next version, and value payload.
/// Output: an opaque write descriptor.
/// Transformation: lets Terlan code build an explicit compare-and-swap write
/// request without accessing store internals.

pub opaque type Write.

/// Builds a portable adapter contract.
/// Input: adapter name, storage family, and capability list.
/// Output: adapter contract descriptor.
/// Transformation: exposes model-sync portability requirements to Terlan code.

pub adapter_contract(name: String, storage_family: String, capabilities: List[Capability]): AdapterContract.

/// Returns true when the expected version matches the current version.
/// Input: expected and current versions.
/// Output: apply predicate.
/// Transformation: exposes compare-and-swap eligibility as a typed predicate.

pub can_apply(expected: Version, current: Version): Bool.

/// Builds a model-sync adapter capability descriptor.
/// Input: capability name.
/// Output: capability descriptor.
/// Transformation: keeps adapter capability declarations explicit at the source
/// boundary.

pub capability(name: String): Capability.

/// Builds a typed conflict descriptor.
/// Input: key, current version, and incoming version.
/// Output: conflict descriptor.
/// Transformation: lets tools and source tests model stale writes explicitly.

pub conflict(key: Key, current_version: Version, incoming_version: Version): Conflict.

/// Builds an optimistic delete descriptor.
/// Input: key, expected version, and tombstone version.
/// Output: delete descriptor.
/// Transformation: exposes compare-and-swap delete intent to Terlan code.

pub delete(key: Key, expected_version: Version, tombstone_version: Version): Delete.

/// Returns the initial optimistic version for a writer.
/// Input: writer id.
/// Output: version descriptor at sequence one.
/// Transformation: gives source code a stable constructor for first writes.

pub initial_version(writer_id: String): Version.

/// Builds a model key descriptor.
/// Input: model name and id.
/// Output: key descriptor.
/// Transformation: validates non-empty model identity through the VM.

pub key(model: String, id: String): Key.

/// Advances an optimistic version for a writer.
/// Input: current version and writer id.
/// Output: next version descriptor.
/// Transformation: keeps sequence advancement in one VM-validated API.

pub next_version(current: Version, writer_id: String): Version.

/// Binds a model-sync adapter contract to a package store.
/// Input: package id and adapter contract.
/// Output: package store adapter binding descriptor.
/// Transformation: lets Terlan code declare that model sync persists through a
/// package-owned storage lane without relying on ORM identity maps.

pub package_store_adapter(package_id: String, contract: AdapterContract): PackageStoreAdapter.

/// Binds a model-sync adapter contract to a persistent actor store.
/// Input: persistent actor id and adapter contract.
/// Output: persistent actor adapter binding descriptor.
/// Transformation: lets Terlan code declare that model sync persists through a
/// VM-owned persistent actor lane.

pub persistent_actor_adapter(actor: std.vm.PersistentActor.ActorId, contract: AdapterContract): PersistentActorAdapter.

/// Returns true when an expected version is older than the current version.
/// Input: expected and current versions.
/// Output: stale-version predicate.
/// Transformation: exposes optimistic concurrency preflight without direct
/// store access.

pub stale(expected: Version, current: Version): Bool.

/// Declares one typed syncable model.
/// Input: model name, key prototype, and portable adapter contract.
/// Output: typed syncable model declaration descriptor.
/// Transformation: makes the public model-sync declaration source-visible while
/// the VM owns versioning, conflict checks, snapshots, change streams, and
/// adapter validation.

pub syncable_model[T](name: String, key: Key, contract: AdapterContract): SyncableModel[T].

/// Builds an optimistic version descriptor.
/// Input: positive sequence and writer id.
/// Output: version descriptor.
/// Transformation: validates monotonic write metadata through the VM.

