/// Input: no value; transition ownership identifies the receiving process.
/// Output: a String allocated in the receiver's actor-local managed heap.
/// Transformation: preserves nonmatching mailbox entries and commits removal
/// only after receiver-side allocation succeeds.

pub receive_string(): String.

/// Receives the first queued message accepted by a predicate.
/// Input: one predicate that accepts a message payload.
/// Output: the first matching message after the current actor resumes.
/// Transformation: scans only the current actor mailbox, preserves skipped
/// messages in order, and parks when no matching payload is available.

pub receive_where[T](predicate: (T) -> Bool): std.vm.Message[T].

/// Releases one resource owned by the current process.
/// Input: an opaque owner-bound resource returned by `acquire`.
/// Output: `true` after the live resource and ownership row are removed.
/// Transformation: validates ownership and performs the same cleanup that an
/// owning process exit would perform, without exposing the resource identity.

pub release[K](resource: Resource[K]): Bool.

/// Builds a typed application resource kind.
/// Input: a positive application-defined kind tag and phantom family `K`.
/// Output: an opaque `ResourceKind[K]`.
/// Transformation: erases to the validated kind tag after type checking.

pub resource_kind[K](tag: Int): ResourceKind[K].

/// Changes the current process scheduling class.
/// Input: one compiler-admitted scheduling class.
/// Output: `Unit` after the VM reclassifies and requeues the process.
/// Transformation: keeps queue ownership, weighted selection, and reduction
/// accounting in the VM scheduler without exposing numeric class tags.

pub schedule(class: SchedulingClass): Unit.

/// Sends one typed message to a process descriptor.
/// Input: one process handle and one VM message descriptor.
/// Output: `Unit` after the VM accepts ownership of the message.
/// Transformation: transfers the typed payload into the recipient mailbox and
/// never exposes its actor-local representation to the sender.

pub send[T]<ActorMessage[T]>(process: Process[T], message: std.vm.Message[T]): Unit.

/// Sends one finite image-owned Atom through the typed direct-AOT mailbox boundary.
/// Input: a positive VM process identity and an Atom admitted by the image table.
/// Output: `Unit` after the VM has published the stable atom identity.
/// Transformation: rejects dynamic atom creation and carries only the canonical
/// finite-table index between processes.

pub send_atom(recipient: Int, payload: Atom): Unit.

/// Sends an immutable Binary through the typed direct-AOT mailbox boundary.
/// Input: a positive VM process identity and an owned Binary value.
/// Output: `Unit` after the VM has copied the packed bits into mailbox ownership.
/// Transformation: preserves the exact bit length while preventing an
/// actor-local binary reference from crossing process ownership.

pub send_binary(recipient: Int, payload: Binary): Unit.

/// Sends immutable Bytes through the typed direct-AOT mailbox boundary.
/// Input: a positive VM process identity and an owned Bytes value.
/// Output: `Unit` after the VM has copied the value into mailbox ownership.
/// Transformation: materializes the sender reference before publication so no
/// actor-local heap reference crosses process ownership.

pub send_bytes(recipient: Int, payload: Bytes): Unit.

/// Sends one scalar Int through the direct-AOT transition boundary.
/// Input: a positive VM process identity and an Int payload.
/// Output: `Unit` after the VM owns and accounts the mailbox delivery.
/// Transformation: exposes the bounded scalar bootstrap for compiled Send
/// transitions while opaque typed Process and Message values remain the public
/// high-level mailbox API.

pub send_int(recipient: Int, payload: Int): Unit.

/// Sends one immutable String through the typed direct-AOT mailbox boundary.
/// Input: a positive VM process identity and an owned immutable String.
/// Output: `Unit` after the VM has copied the value into mailbox ownership.
/// Transformation: materializes the sender reference before publication so no
/// actor-local heap reference crosses process ownership.

pub send_string(recipient: Int, payload: String): Unit.

/// Suspends the current process until a timer expires.
/// Input: one typed VM timer descriptor.
/// Output: `Unit` after the VM-owned one-shot timer reaches its deadline.
/// Transformation: keeps clock ordering, parking, and continuation wakeup in
/// the VM scheduler.

pub sleep(timer: Timer): Unit.

/// Starts a local VM process.
/// Input: one image-local `Entry[T]` descriptor.
/// Output: a VM-owned `Process[T]` handle.
/// Transformation: spawns a scheduler-visible child without exposing its
/// numeric process identity to source code.

pub spawn[T](entry: Entry[T]): Process[T].

/// Builds a VM timer descriptor.
/// Input: a positive deterministic VM tick count.
/// Output: an opaque `Timer`.
/// Transformation: erases to the validated tick count after type checking.

pub timer(ticks: Int): Timer.

/// Removes the current process's symmetric link to one peer.
/// Input: a typed process handle previously linked to the current process.
/// Output: `true` when a live relationship was removed, otherwise `false`.
/// Transformation: validates ownership and updates both link endpoints before
/// the current continuation resumes.

pub unlink[T](peer: Process[T]): Bool.

/// Voluntarily yields the current process at an AOT continuation boundary.
/// Input: no value.
/// Output: `Unit` after the process is selected to resume.
/// Transformation: parks only the current process and transfers a stable typed
/// continuation to the VM scheduler; it never exposes a native stack address.

pub yield_now(): Unit.

/// ActorMessage marks payloads that may enter a local VM process mailbox.
/// Input: actor message payload type `T`.
/// Output: an identity proof method used by generic mailbox boundaries.
/// Transformation: keeps local actor messages typed while allowing a concrete
/// `impl not ActorMessage[LocalType]` to prohibit mailbox delivery at compile
/// time.

pub trait ActorMessage[T] {
    message(value: T): T.
}.

/// ProcessLike defines the minimum typed process operations.
/// Input: process handle type `P` and message payload type `T`.
/// Output: a trait requiring `send` and `stop` operations.
/// Transformation: models runtime message delivery as receiver-style API surface
/// instead of Terlan-specific process operators.

pub trait ProcessLike[P, T] extends ActorMessage[T] {
    send(process: P, message: Message[T]): Unit.
    stop(process: P): Unit.
}.

pub impl ActorMessage[T] for T {
}.

//! Terlan VM distributed scheduler contract.
//! `std.vm.Scheduler` executes local placement and migration-plan state changes.
//! Values are immutable actor-owned plans: each update returns a new scheduler
//! value and leaves its input unchanged. Migration phases and commits describe
//! that plan's control state; they do not transfer actor heaps, continuations,
//! mailboxes, timers, or network traffic. Live actor migration is unsupported.
//! Node membership and load are supplied explicitly by the caller.

module std.vm.Scheduler.

/// Event represents one scheduler notification.
/// Input: placement, migration, throttling, or partition-response event data.
/// Output: an opaque scheduler event descriptor.
/// Transformation: exposes a typed event stream while the VM owns event
/// sequencing and replay safety.

pub opaque type Event.

/// Migration represents one controlled migration intent or outcome.
/// Input: actor identity, source node, target node, and statefulness flag.
/// Output: an opaque migration descriptor.
/// Transformation: records snapshot, transfer, resume, rollback, and abort
/// lifecycle state under VM ownership.

pub opaque type Migration.

/// MigrationOutcome represents one terminal migration result.
/// Input: a committed, rolled-back, or aborted migration transition.
/// Output: opaque outcome with kind, sequence, and optional reason metadata.
/// Transformation: keeps terminal replay records VM-owned while exposing typed
/// source inspection.

pub opaque type MigrationOutcome.

/// MigrationOutcomeResult carries a terminal outcome and updated scheduler.
/// Input: one successful terminal migration transition.
/// Output: immutable scheduler and outcome values from the same transition.
/// Transformation: preserves the terminal event and exactly-once replay record
/// in the scheduler state returned to source code.

pub opaque type MigrationOutcomeResult.

/// MigrationResult carries a migration state and its updated scheduler.
/// Input: one successful migration request or phase transition.
/// Output: immutable scheduler and migration values from the same transition.
/// Transformation: keeps migration sequencing and event state synchronized in
/// source code without exposing the VM scheduler representation.

pub opaque type MigrationResult.

/// Node represents one schedulable VM cluster node.
/// Input: node identity and lifecycle state.
/// Output: an opaque scheduler node descriptor.
/// Transformation: keeps membership and load metadata inside the VM scheduler
/// while allowing Terlan source to build placement scenarios.

pub opaque type Node.

/// Placement represents one VM placement decision.
/// Input: actor identity and scheduling policy.
/// Output: an opaque placement descriptor with selected node metadata.
/// Transformation: records deterministic placement outcomes without leaking the
/// scheduler table representation.

pub opaque type Placement.

/// PlacementResult carries a placement decision and its updated scheduler.
/// Input: one successful VM placement transition.
/// Output: immutable scheduler and placement values from the same transition.
/// Transformation: forces source code to thread the scheduler state that owns
/// the new placement assignment and event.

pub opaque type PlacementResult.

/// Policy represents one placement policy descriptor.
/// Input: policy constructor arguments such as pinned node or shard key.
/// Output: an opaque scheduling policy.
/// Transformation: keeps policy validation in the VM while exposing stable
/// source-level placement choices.

pub opaque type Policy.

/// Scheduler represents one distributed scheduling table.
/// Input: active node descriptors and policy decisions.
/// Output: an opaque scheduler descriptor.
/// Transformation: owns placement state, shard ownership, migration state, and
/// event ordering inside the VM runtime.

pub opaque type Scheduler.

/// Aborts an in-flight migration with a non-empty reason.
/// Input: scheduler receiver, migration descriptor, and reason.
/// Output: aborted outcome and updated scheduler.
/// Transformation: terminates the in-flight migration and records a replayable
/// abort event under VM ownership.

pub (scheduler: Scheduler) abort_migration(migration: Migration, reason: String): MigrationOutcomeResult.

/// Advances a local migration-plan phase.
/// Input: scheduler receiver, migration descriptor, and phase tag.
/// Output: migration transition with the updated intent and scheduler.
/// Transformation: delegates legal phase ordering to the VM scheduler.

pub (scheduler: Scheduler) advance_migration(migration: Migration, phase: String): MigrationResult.

/// Commits a local migration plan that has reached the resuming phase.
/// Input: scheduler receiver and current migration descriptor.
/// Output: committed outcome and updated scheduler.
/// Transformation: validates actor and sequence identity, records the terminal
/// outcome, and emits one ordered commit event. This does not move a live actor.

pub (scheduler: Scheduler) commit_migration(migration: Migration): MigrationOutcomeResult.

/// Declares an actor-group policy override inside one route.
/// Input: scheduler receiver, route id, actor-group id, and policy descriptor.
/// Output: updated scheduler descriptor.
/// Transformation: records the most specific placement policy scope without
/// exposing the VM scheduler registry.

pub (scheduler: Scheduler) declare_actor_group_policy(route_id: String, actor_group_id: String, policy: Policy): Scheduler.

/// Declares a route-level placement policy override.
/// Input: scheduler receiver, route id, and policy descriptor.
/// Output: updated scheduler descriptor.
/// Transformation: records one immutable route policy declaration; repeating
/// the same declaration is idempotent and conflicting declarations fail.

pub (scheduler: Scheduler) declare_route_policy(route_id: String, policy: Policy): Scheduler.

/// Reads scheduler events after an event cursor.
/// Input: scheduler receiver and last observed event sequence.
/// Output: ordered event descriptors.
/// Transformation: exposes typed scheduler notifications without leaking the
/// internal event log representation.

pub (scheduler: Scheduler) events_after(last_event_sequence: Int): List[Event].

/// Builds a least-connections placement policy.
/// Input: no runtime input.
/// Output: policy descriptor.
/// Transformation: asks the VM to use tracked connection load with stable
/// tie-breaks.

pub least_connections(): Policy.

/// Returns the migration value from a migration transition.

pub migration(result: MigrationResult): Migration.

/// Returns the actor id tracked by a migration.

pub migration_actor_id(migration: Migration): String.

/// Returns the source node id tracked by a migration.

pub migration_from_node_id(migration: Migration): String.

/// Returns the current migration phase name.

pub migration_phase(migration: Migration): String.

/// Returns the updated scheduler from a migration transition.

pub migration_scheduler(result: MigrationResult): Scheduler.

/// Returns the monotonic migration sequence.

pub migration_sequence(migration: Migration): Int.

/// Reports whether a migration carries actor state.

pub migration_stateful(migration: Migration): Bool.

/// Returns the target node id tracked by a migration.

pub migration_to_node_id(migration: Migration): String.

/// Builds a distributed scheduler from a node set.
/// Input: node descriptors.
/// Output: scheduler descriptor.
/// Transformation: delegates active-node filtering and invalid-membership
/// rejection to the VM distributed scheduler.

pub new(nodes: List[Node]): Scheduler.

/// Builds one schedulable VM node descriptor.
/// Input: node id and lifecycle state such as `active` or `unreachable`.
/// Output: node descriptor.
/// Transformation: normalizes node state for source-level scheduler scenarios.

pub node(node_id: String, state: String): Node.

/// Returns the terminal outcome from a migration transition.

pub outcome(result: MigrationOutcomeResult): MigrationOutcome.

/// Returns `committed`, `rolled_back`, or `aborted`.

pub outcome_kind(outcome: MigrationOutcome): String.

/// Returns the terminal reason, or an empty String for commit.

pub outcome_reason(outcome: MigrationOutcome): String.

/// Returns the updated scheduler from a terminal migration transition.

pub outcome_scheduler(result: MigrationOutcomeResult): Scheduler.

/// Returns the migration sequence associated with an outcome.

pub outcome_sequence(outcome: MigrationOutcome): Int.

/// Builds a pinned-node placement policy.
/// Input: node id.
/// Output: policy descriptor.
/// Transformation: asks the VM to validate that the target node is active
/// before placing the actor.

pub pinned(node_id: String): Policy.

/// Places one actor using a policy.
/// Input: scheduler receiver, actor id, and policy descriptor.
/// Output: placement transition with the decision and updated scheduler.
/// Transformation: produces a deterministic placement decision and scheduler
/// event inside the VM while preserving immutable source state.

pub (scheduler: Scheduler) place(actor_id: String, policy: Policy): PlacementResult.

/// Places an actor using actor-group, route, then default policy precedence.
/// Input: scheduler receiver, actor id, route id, actor-group id, and default
/// policy.
/// Output: placement transition with the decision and updated scheduler.
/// Transformation: resolves the most specific declared policy deterministically
/// before delegating placement to the VM scheduler.

pub (scheduler: Scheduler) place_for_actor_group(actor_id: String, route_id: String, actor_group_id: String, default_policy: Policy): PlacementResult.

/// Places an actor with a route policy override.
/// Input: scheduler receiver, actor id, route id, and call-site default policy.
/// Output: placement transition with the decision and updated scheduler.
/// Transformation: uses the declared route policy when present and otherwise
/// applies the supplied default policy.

pub (scheduler: Scheduler) place_for_route(actor_id: String, route_id: String, default_policy: Policy): PlacementResult.

/// Returns the placement decision from a placement transition.

pub placement(result: PlacementResult): Placement.

/// Returns the actor id recorded by a placement decision.

pub placement_actor_id(placement: Placement): String.

/// Reports whether placement used the policy fallback path.

pub placement_fallback_used(placement: Placement): Bool.

/// Returns the selected node id from a placement decision.

pub placement_node_id(placement: Placement): String.

/// Returns the policy name recorded by a placement decision.

pub placement_policy(placement: Placement): String.

/// Returns the updated scheduler from a placement transition.

pub placement_scheduler(result: PlacementResult): Scheduler.

/// Refreshes scheduler membership from a new node set.
/// Input: scheduler receiver and replacement node descriptors.
/// Output: updated scheduler descriptor.
/// Transformation: removes inactive placement targets and preserves scheduler
/// state that remains valid after membership changes.

pub (scheduler: Scheduler) refresh(nodes: List[Node]): Scheduler.

/// Adds a migration intent to a local plan.
/// Input: scheduler receiver, actor id, source node, target node, and
/// statefulness flag.
/// Output: migration transition with the intent and updated scheduler.
/// Transformation: records intent metadata and sequencing. It does not start
/// snapshot, transfer, or actor-resume work.

pub (scheduler: Scheduler) request_migration(actor_id: String, from_node_id: String, to_node_id: String, stateful: Bool): MigrationResult.

/// Rolls back an in-flight migration with a non-empty reason.
/// Input: scheduler receiver, migration descriptor, and reason.
/// Output: rolled-back outcome and updated scheduler.
/// Transformation: removes the in-flight migration and records a replayable
/// rollback event under VM ownership.

pub (scheduler: Scheduler) rollback_migration(migration: Migration, reason: String): MigrationOutcomeResult.

/// Builds a round-robin placement policy.
/// Input: no runtime input.
/// Output: policy descriptor.
/// Transformation: asks the VM to place actors across active nodes in stable
/// deterministic order.

pub round_robin(): Policy.

/// Builds a shard-affinity policy with explicit fallback behavior.
/// Input: shard key and fallback tag such as `reject` or `round_robin`.
/// Output: policy descriptor.
/// Transformation: lets the VM choose deterministic shard ownership and record
/// whether fallback was required.

pub shard_affinity(shard_key: String, fallback: String): Policy.

/// Updates tracked load for one node.
/// Input: scheduler receiver, node id, and active connection count.
/// Output: updated scheduler descriptor.
/// Transformation: records load in the VM-owned scheduler table for later
/// least-connections placement.

pub (scheduler: Scheduler) update_load(node_id: String, active_connections: Int): Scheduler.

//! Typed supervision policy composed over VM-owned lifecycle mechanics.

module std.vm.Supervisor.

/// One stable child declaration and its current process identity.

pub struct ChildSnapshot {
    id: Int,
    process_id: Int,
    restart_count: Int,
    running: Bool,
    pending_restart: Bool,
    last_backoff: Int,
    shutdown_timeout: Int
}.

/// Typed child declaration consumed by VM-owned supervision admission.

pub type ChildSpec[P] =
    {Atom["supervisor_child"], id: Int, value: P, restart_class: RestartClass, order: Int, initial_backoff: Int, maximum_backoff: Int, shutdown_timeout: Int}.

pub type ChildSpecTag =
    Atom["supervisor_child"].

pub type OneForAll =
    Atom["one_for_all"].

pub type OneForOne =
    Atom["one_for_one"].

pub type Permanent =
    Atom["permanent"].

/// One committed event following the stored snapshot.

pub struct PersistedEvent {
    sequence: Int,
    payload: std.vm.Bytes
}.

/// Durable recovery binding. The restore entry runs after a restart and calls
/// restore() to load the validated snapshot and committed event suffix.

pub type Recovery[T] =
    {Atom["supervisor_recovery"], path: String, schema: String, version: Int, restore_entry: std.vm.Process.Entry[T]}.

/// Validated state and ordered events loaded for the current logical child.

pub struct RecoveryState {
    generation: Int,
    sequence: Int,
    state: std.vm.Bytes,
    events: List[PersistedEvent]
}.

pub type RestForOne =
    Atom["rest_for_one"].

pub type RestartClass =
    Permanent
  | Transient
  | Temporary.

/// An actual VM restart decision, including the replacement identity, if any.

pub struct RestartEvent {
    child_id: Int,
    old_process_id: Int,
    new_process_id: Int,
    restart_count: Int,
    reason: String,
    outcome: String,
    backoff: Int
}.

pub type RestartStrategy =
    OneForOne
  | OneForAll
  | RestForOne.

/// Immutable policy identity for one VM-owned supervisor node.

pub type Supervisor =
    {Atom["supervisor"], name: Int, strategy: RestartStrategy, restart_limit: Int, restart_window: Int}.

/// A rejected admission, lookup, persistence, or shutdown operation.

pub struct SupervisorError {
    message: String
}.

/// Immutable inspection evidence from the running supervision graph.

pub struct SupervisorSnapshot {
    running: Bool,
    children: List[ChildSnapshot],
    restart_history: List[RestartEvent]
}.

pub type SupervisorTag =
    Atom["supervisor"].

pub type Temporary =
    Atom["temporary"].

pub type Transient =
    Atom["transient"].

/// Appends one ordered event to the calling supervised child's durable store.

pub append_event(sequence: Int, payload: std.vm.Bytes): Result[Unit, SupervisorError].

@pure
pub cap_backoff(delay: Int, maximum: Int): Int.

/// Stores a durable snapshot for the calling supervised child.

pub checkpoint(sequence: Int, state: std.vm.Bytes): Result[Unit, SupervisorError].

/// Builds a typed child declaration without exposing a host tuple protocol.

pub child_spec[P](id: Int, value: P, restart_class: RestartClass, order: Int, initial_backoff: Int, maximum_backoff: Int, shutdown_timeout: Int): ChildSpec[P].

/// Resolves the current replacement using the original typed declaration.

pub current_child[T](supervisor: Supervisor, spec: ChildSpec[std.vm.Process.Entry[T]]): Result[std.vm.Process[T], SupervisorError].

/// Builds the durable store and recovery-entry binding for one child.

pub recovery[T](path: String, schema: String, version: Int, restore_entry: std.vm.Process.Entry[T]): Recovery[T].

/// Computes capped exponential backoff for a one-based restart attempt.

@pure
pub restart_backoff(initial: Int, maximum: Int, attempt: Int): Int.

/// Reopens the durable store and validates the declared schema before replay.

pub restore(): Result[RecoveryState, SupervisorError].

/// Builds one source-owned policy value; the VM owns its mutable graph.

pub root(name: Int, strategy: RestartStrategy, restart_limit: Int, restart_window: Int): Supervisor.

@pure
pub scale_backoff(delay: Int, attempt: Int): Int.

/// Selects one child under one-for-one, one-for-all, or rest-for-one.

@pure
pub selects_child(strategy: RestartStrategy, failed_order: Int, candidate_order: Int): Bool.

/// Selects whether a child class restarts for a normal or abnormal exit.

@pure
pub should_restart(restart_class: RestartClass, abnormal: Bool): Bool.

/// Decides whether an ordered shutdown deadline has expired.

@pure
pub shutdown_expired(start_tick: Int, timeout: Int, now_tick: Int): Bool.

/// Reads actual children, replacement identities, and restart decisions.

pub snapshot(supervisor: Supervisor): Result[SupervisorSnapshot, SupervisorError].

/// Admits and starts an image entry in the calling actor's supervision tree.
/// Names are local to that owner. Time policies use monotonic VM clock ticks.
/// Ordinary Process.spawn remains unsupervised.

pub start_child[T](supervisor: Supervisor, spec: ChildSpec[std.vm.Process.Entry[T]]): Result[std.vm.Process[T], SupervisorError].

/// Registers a durable child with distinct initial and recovery entry points.

pub start_persistent_child[T](supervisor: Supervisor, spec: ChildSpec[std.vm.Process.Entry[T]], recovery: Recovery[T]): Result[std.vm.Process[T], SupervisorError].

/// Requests shutdown and suppresses future restarts for this declaration.

pub stop_child[T](supervisor: Supervisor, spec: ChildSpec[std.vm.Process.Entry[T]]): Result[Unit, SupervisorError].

/// Enforces a finite restart-intensity budget before escalation.

@pure
pub within_intensity(restart_count: Int, restart_limit: Int): Bool.

/// Contract implemented by values that expose their own hard lifecycle primitives.

pub trait Supervised[P] {
    child_spec(value: P): ChildSpec[P].
    start(supervisor: Supervisor, spec: ChildSpec[P]): Result[P, Error].
    stop(supervisor: Supervisor, value: P): Unit.
}.

//! Terlan VM TCP socket contract.
//! `std.vm.Tcp` exposes the minimum active socket surface needed by
//! runtime-targeted integration tests and protocol adapters. It is not a portable
//! networking API.

module std.vm.Tcp.

/// TcpListener represents a VM-owned TCP listener.
/// Input: no runtime input.
/// Output: an opaque target-owned listener handle.
/// Transformation: keeps listener identity and accept backlog ownership inside
/// the VM while allowing typed accept and lifecycle operations.

pub opaque type TcpListener.

/// TcpSocket represents a connected TCP socket owned by the selected VM runtime.
/// Input: no runtime input.
/// Output: an opaque target-owned socket handle.
/// Transformation: keeps runtime socket identity and lifecycle out of portable
/// Terlan values while allowing typed send/receive operations.

pub opaque type TcpSocket.

/// Accepts a connected socket from a listener.
/// Input: a listener receiver and timeout.
/// Output: `Ok(TcpSocket)` when a connection is accepted, otherwise
/// `Err(Error)`.
/// Transformation: parks or resumes through the VM scheduler while preserving
/// listener ownership inside the VM runtime.

pub (listener: TcpListener) accept(timeout: std.vm.Timeout): Result < TcpSocket, std.core.Error >.

/// Closes a connected socket.
/// Input: a mutable socket receiver.
/// Output: `Unit`.
/// Transformation: asks the selected VM runtime to close and release the socket handle.

pub (mut socket: TcpSocket) close(): Unit.

/// Closes a TCP listener.
/// Input: a mutable listener receiver.
/// Output: `Unit`.
/// Transformation: asks the selected VM runtime to close and release the
/// listener handle.

pub (mut listener: TcpListener) close_listener(): Unit.

/// Connects to a TCP endpoint.
/// Input: host name or address, port number, and timeout.
/// Output: `Ok(TcpSocket)` on connection, otherwise `Err(Error)`.
/// Transformation: delegates DNS, socket creation, and connection failure
/// normalization to the selected VM runtime.

pub connect(host: String, port: Int, timeout: std.vm.Timeout): Result[TcpSocket, std.core.Error].

/// Starts listening on a TCP address.
/// Input: a runtime address such as `127.0.0.1:8080`.
/// Output: `Ok(TcpListener)` when the VM owns the listener, otherwise
/// `Err(Error)`.
/// Transformation: delegates address binding, listener ownership, and resource
/// diagnostics to the selected VM runtime.

pub listen(address: String): Result < TcpListener, std.core.Error >.

/// Starts listening on a TCP address with an explicit accept backlog.
/// Input: a runtime address and positive backlog capacity.
/// Output: `Ok(TcpListener)` when the VM owns the listener, otherwise
/// `Err(Error)`.
/// Transformation: delegates bounded accept queue setup to the VM runtime so
/// overloaded listeners expose backpressure instead of hidden host queues.

pub listen_with_backlog(address: String, backlog: Int): Result < TcpListener, std.core.Error >.

/// Receives bytes from a connected socket.
/// Input: a socket receiver, maximum byte count, and timeout.
/// Output: `Ok(Bytes)` when bytes are read, otherwise `Err(Error)`.
/// Transformation: delegates receive buffering and timeout behavior to the
/// selected VM runtime while keeping the protocol frame typed as `Bytes`.

pub (socket: TcpSocket) receive(max_bytes: Int, timeout: std.vm.Timeout): Result[std.vm.Bytes, std.core.Error].

/// Sends bytes on a connected socket.
/// Input: a socket receiver and a byte buffer.
/// Output: `Ok(Unit)` on successful write, otherwise `Err(Error)`.
/// Transformation: asks the selected VM runtime to send the binary frame and
/// report target socket failures through the standard error channel.

pub (socket: TcpSocket) send(bytes: std.vm.Bytes): Result[Unit, std.core.Error].

//! Terlan VM timeout contract.
//! `std.vm.Timeout` gives runtime-targeted tests and runtime adapters a typed
//! duration value for receive, socket, and port operations.

module std.vm.Timeout.

/// Timeout represents a millisecond timeout value.
/// Input: no runtime input.
/// Output: an immutable managed timeout value.
/// Transformation: stores a finite duration or an unbounded wait in a private
/// field. Constructing and inspecting a timeout does not access the runtime.

pub struct Timeout {
    #milliseconds: Option[Int]
}.

/// Builds an infinite timeout.
/// Input: no runtime input.
/// Output: a `Timeout` that waits until the target operation completes.
/// Transformation: stores the absence of a finite deadline.

@pure
pub forever(): Timeout.

/// Builds a finite timeout in milliseconds.
/// Input: non-negative millisecond count.
/// Output: a finite `Timeout`.
/// Transformation: validates the non-negative count in source and stores it.
/// Negative counts fail the guarded match; they are not clamped or made infinite.

pub milliseconds(value: Int): Timeout.

/// Checks whether a timeout would wake after elapsed milliseconds.
/// Input: one `Timeout` and a non-negative elapsed millisecond count.
/// Output: `true` when a finite timeout is due; `false` for `forever` or an
/// elapsed value before the finite deadline.
/// Transformation: exposes deterministic timer wakeup behavior for source-level
/// VM validation without sleeping or delegating to a host runtime. Negative
/// elapsed counts fail the guarded match, including for unbounded waits.

@pure
pub wakes_after(timeout: Timeout, elapsed_ms: Int): Bool.

//! WebAssembly ABI scalar types.
//! `std.wasm.Abi` names WebAssembly boundary scalar types used by the
//! `wasm.core` target. These aliases keep exported function signatures explicit
//! without requiring redundant annotations.

module std.wasm.Abi.

/// WebAssembly 32-bit floating-point ABI scalar.
/// Input: no runtime input.
/// Output: a `Float` value represented as Wasm `f32` at the export boundary.
/// Transformation: narrows finite Terlan float literals and values to the
/// explicit Wasm scalar selected by the declaration.

pub type F32 =
    Float.

/// WebAssembly 64-bit floating-point ABI scalar.
/// Input: no runtime input.
/// Output: a `Float` value represented as Wasm `f64` at the export boundary.
/// Transformation: preserves Terlan float precision at the Wasm boundary.

pub type F64 =
    Float.

/// WebAssembly 32-bit integer ABI scalar.
/// Input: no runtime input.
/// Output: an `Int` value represented as Wasm `i32` at the export boundary.
/// Transformation: aliases portable Terlan `Int` to the explicit WebAssembly
/// ABI spelling used by `terlc build --target wasm.core`.

pub type I32 =
    Int.

/// WebAssembly 64-bit integer ABI scalar.
/// Input: no runtime input.
/// Output: an `Int` value represented as Wasm `i64` at the export boundary.
/// Transformation: preserves the explicit width required by host calls and
/// artifact manifests.

pub type I64 =
    Int.

